{
  "name": "SoloPreneur AI E-Book Architect",
  "description": "An automated AI agent workflow to generate comprehensive e-books from a single topic idea. Features specialized agents for outlining, writing, and cover design."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Chapter {
  id: string;
  title: string;
  content?: string;
  status: 'pending' | 'generating' | 'completed' | 'error';
}

export interface EBook {
  topic: string;
  title: string;
  targetAudience: string;
  description: string;
  chapters: Chapter[];
  coverImage?: string;
}

export enum AgentRole {
  STRATEGIST = 'Strategist (นักวางกลยุทธ์)',
  WRITER = 'Writer (นักเขียน)',
  DESIGNER = 'Designer (นักออกแบบ)',
  REVIEWER = 'Reviewer (บรรณาธิการ)'
}

export interface LogEntry {
  timestamp: Date;
  agent: AgentRole;
  message: string;
}

export enum WorkflowStep {
  INPUT = 0,
  OUTLINE = 1,
  WRITING = 2,
  DESIGN = 3,
  COMPLETED = 4
}

import { GoogleGenAI, Type } from "@google/genai";
import { Chapter, EBook } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key is missing. Please set process.env.API_KEY");
  }
  return new GoogleGenAI({ apiKey });
};

// 1. Agent: Strategist - Creates the Outline
export const generateBookOutline = async (topic: string): Promise<Partial<EBook>> => {
  const ai = getClient();

  const prompt = `
    You are an expert E-Book Strategist and Publisher.
    Your task is to plan a non-fiction e-book based on the user's topic: "${topic}".

    1. Create a catchy Title.
    2. Define the Target Audience.
    3. Write a short Description.
    4. Create an outline with exactly 4 distinct chapters.

    The content must be in Thai Language.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          targetAudience: { type: Type.STRING },
          description: { type: Type.STRING },
          chapters: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                summary: { type: Type.STRING } // Helper for the writer later
              },
              required: ["title", "summary"]
            }
          }
        },
        required: ["title", "targetAudience", "description", "chapters"]
      }
    }
  });

  if (!response.text) throw new Error("Failed to generate outline");

  const data = JSON.parse(response.text);

  // Transform to our internal Chapter type
  const chapters: Chapter[] = data.chapters.map((c: any, index: number) => ({
    id: `ch-${index}`,
    title: c.title,
    content: '',
    status: 'pending'
  }));

  return {
    title: data.title,
    targetAudience: data.targetAudience,
    description: data.description,
    chapters: chapters
  };
};

// 2. Agent: Writer - Writes a specific chapter
export const generateChapterContent = async (
  bookTitle: string, 
  chapterTitle: string, 
  audience: string
): Promise<string> => {
  const ai = getClient();

  const prompt = `
    You are a professional Ghostwriter.
    Write the content for a chapter in an e-book.

    Book Title: ${bookTitle}
    Target Audience: ${audience}
    Chapter Title: ${chapterTitle}

    Requirements:
    - Language: Thai (Formal but accessible).
    - Length: Approximately 400-500 words.
    - Structure: Use headers, bullet points where appropriate, and a concluding summary.
    - Format: Markdown.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: prompt,
  });

  return response.text || "Failed to generate content.";
};

// 3. Agent: Designer - Creates the Cover Image
export const generateCoverImage = async (title: string, description: string): Promise<string> => {
  const ai = getClient();

  // First, generate a prompt for the image model based on the book info
  const promptDesignResponse = await ai.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: `Create a highly detailed, artistic image generation prompt for an e-book cover. 
    Book Title: "${title}". 
    Description: "${description}".
    Style: Minimalist, Modern, Professional, High contrast. 
    Output only the English prompt text.`
  });

  const imagePrompt = promptDesignResponse.text || `A professional book cover for ${title}`;

  // Generate the actual image
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview', // Using the advanced image model
      contents: {
        parts: [{ text: imagePrompt }]
      },
      config: {
        imageConfig: {
            aspectRatio: "3:4", // Standard book ratio
            imageSize: "1K"
        }
      }
    });

    // Extract image
    for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
            return `data:image/png;base64,${part.inlineData.data}`;
        }
    }

    throw new Error("No image data returned");

  } catch (e) {
    console.error("Image gen error", e);
    return "https://picsum.photos/600/800"; // Fallback
  }
};

import React, { useEffect, useRef } from 'react';
import { LogEntry, AgentRole } from '../types';

interface AgentLogProps {
  logs: LogEntry[];
}

const getAgentColor = (role: AgentRole) => {
  switch (role) {
    case AgentRole.STRATEGIST: return 'text-purple-600 bg-purple-100';
    case AgentRole.WRITER: return 'text-blue-600 bg-blue-100';
    case AgentRole.DESIGNER: return 'text-pink-600 bg-pink-100';
    case AgentRole.REVIEWER: return 'text-emerald-600 bg-emerald-100';
    default: return 'text-gray-600 bg-gray-100';
  }
};

export const AgentLog: React.FC<AgentLogProps> = ({ logs }) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [logs]);

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 h-64 flex flex-col overflow-hidden">
      <div className="p-3 bg-slate-50 border-b border-slate-200 font-semibold text-slate-700 flex justify-between items-center">
        <span>System Activity Log</span>
        <span className="text-xs font-normal text-slate-500">Live Feed</span>
      </div>
      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        {logs.length === 0 && (
          <p className="text-center text-slate-400 italic text-sm mt-10">Waiting for input...</p>
        )}
        {logs.map((log, index) => (
          <div key={index} className="flex gap-3 items-start animate-fade-in">
            <div className="min-w-[4rem] text-xs text-slate-400 mt-1">
              {log.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
            </div>
            <div className="flex-1">
              <span className={`inline-block px-2 py-0.5 rounded text-xs font-bold mr-2 mb-1 ${getAgentColor(log.agent)}`}>
                {log.agent}
              </span>
              <p className="text-sm text-slate-700">{log.message}</p>
            </div>
          </div>
        ))}
        <div ref={bottomRef} />
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { EBook } from '../types';
import ReactMarkdown from 'react-markdown'; // We don't have this, so we'll simulate or just render text

interface BookPreviewProps {
  ebook: EBook;
  onRestart: () => void;
}

export const BookPreview: React.FC<BookPreviewProps> = ({ ebook, onRestart }) => {
  const [activeChapter, setActiveChapter] = useState(0);

  // Simple renderer since we can't import react-markdown in this environment easily without package.json
  const renderContent = (text: string) => {
    return text.split('\n').map((line, i) => (
      <React.Fragment key={i}>
        {line.startsWith('#') ? (
            <h3 className="text-xl font-bold mt-4 mb-2 text-slate-800">
                {line.replace(/^#+\s/, '')}
            </h3>
        ) : (
            <p className="mb-2 text-slate-600 leading-relaxed">{line}</p>
        )}
      </React.Fragment>
    ));
  };

  return (
    <div className="flex flex-col lg:flex-row gap-8 h-full">
      {/* Sidebar / Cover */}
      <div className="w-full lg:w-1/3 flex flex-col gap-6">
        <div className="bg-white p-4 rounded-xl shadow-lg border border-slate-200 transform hover:scale-[1.02] transition-transform duration-300">
            {ebook.coverImage ? (
                <img 
                    src={ebook.coverImage} 
                    alt="Book Cover" 
                    className="w-full rounded-lg shadow-inner aspect-[3/4] object-cover"
                />
            ) : (
                <div className="w-full aspect-[3/4] bg-slate-200 rounded-lg flex items-center justify-center text-slate-400">
                    No Cover
                </div>
            )}
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
            <h1 className="text-2xl font-bold text-slate-900 mb-2">{ebook.title}</h1>
            <p className="text-sm text-slate-500 mb-4">{ebook.targetAudience}</p>
            <p className="text-slate-700 text-sm italic">{ebook.description}</p>
        </div>

        <button 
            onClick={onRestart}
            className="w-full py-3 bg-slate-800 text-white rounded-lg hover:bg-slate-900 transition-colors font-medium"
        >
            Start New Project
        </button>
      </div>

      {/* Content Reader */}
      <div className="w-full lg:w-2/3 bg-white rounded-xl shadow-lg border border-slate-200 flex flex-col h-[800px]">
        {/* Reader Header */}
        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
            <h2 className="font-semibold text-slate-700">Book Content Preview</h2>
            <div className="text-sm text-slate-500">
                Chapter {activeChapter + 1} of {ebook.chapters.length}
            </div>
        </div>

        <div className="flex flex-1 overflow-hidden">
            {/* TOC */}
            <div className="w-1/3 border-r border-slate-100 overflow-y-auto bg-slate-50/50">
                <ul className="divide-y divide-slate-100">
                    {ebook.chapters.map((chapter, idx) => (
                        <li key={chapter.id}>
                            <button
                                onClick={() => setActiveChapter(idx)}
                                className={`w-full text-left p-4 text-sm hover:bg-slate-100 transition-colors ${activeChapter === idx ? 'bg-indigo-50 text-indigo-700 font-medium border-l-4 border-indigo-500' : 'text-slate-600'}`}
                            >
                                <span className="block text-xs text-slate-400 mb-1">Chapter {idx + 1}</span>
                                {chapter.title}
                            </button>
                        </li>
                    ))}
                </ul>
            </div>

            {/* Content */}
            <div className="w-2/3 overflow-y-auto p-8 bg-white">
                <h2 className="text-3xl font-bold text-slate-800 mb-8 border-b pb-4">
                    {ebook.chapters[activeChapter].title}
                </h2>
                <div className="prose prose-slate max-w-none">
                    {renderContent(ebook.chapters[activeChapter].content || "Content not available.")}
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Chapter, EBook, AgentRole, LogEntry, WorkflowStep } from './types';
import { generateBookOutline, generateChapterContent, generateCoverImage } from './services/geminiService';
import { AgentLog } from './components/AgentLog';
import { BookPreview } from './components/BookPreview';
import { BeakerIcon, BookOpenIcon, PencilIcon, SparklesIcon, ChevronRightIcon } from '@heroicons/react/24/solid';

const App: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [step, setStep] = useState<WorkflowStep>(WorkflowStep.INPUT);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [eBook, setEBook] = useState<Partial<EBook>>({ chapters: [] });
  const [isProcessing, setIsProcessing] = useState(false);

  const addLog = (agent: AgentRole, message: string) => {
    setLogs(prev => [...prev, { timestamp: new Date(), agent, message }]);
  };

  const handleStart = async () => {
    if (!topic.trim()) return;
    setStep(WorkflowStep.OUTLINE);
    setIsProcessing(true);
    setLogs([]); // Clear previous logs

    try {
      // Step 1: Strategy
      addLog(AgentRole.STRATEGIST, `Analyzing topic: "${topic}"...`);
      addLog(AgentRole.STRATEGIST, "Researching market trends and target audience.");

      const outlineData = await generateBookOutline(topic);
      setEBook(outlineData);
      addLog(AgentRole.STRATEGIST, `Outline created: "${outlineData.title}" with ${outlineData.chapters?.length} chapters.`);

      // Move to writing automatically
      setTimeout(() => setStep(WorkflowStep.WRITING), 1500);

    } catch (error) {
      addLog(AgentRole.STRATEGIST, `Error: ${(error as Error).message}`);
      setIsProcessing(false);
      setStep(WorkflowStep.INPUT);
    }
  };

  // Effect to handle the Writing Phase
  useEffect(() => {
    const processWriting = async () => {
      if (step === WorkflowStep.WRITING && eBook.chapters && eBook.chapters.length > 0) {

        const newChapters = [...eBook.chapters];

        for (let i = 0; i < newChapters.length; i++) {
          const chapter = newChapters[i];
          if (chapter.status === 'pending') {
            // Update UI to show generating
            newChapters[i].status = 'generating';
            setEBook(prev => ({ ...prev, chapters: [...newChapters] }));

            addLog(AgentRole.WRITER, `Starting Chapter ${i + 1}: ${chapter.title}`);

            try {
              const content = await generateChapterContent(
                eBook.title || "Book", 
                chapter.title, 
                eBook.targetAudience || "General Reader"
              );

              newChapters[i].content = content;
              newChapters[i].status = 'completed';
              setEBook(prev => ({ ...prev, chapters: [...newChapters] }));
              addLog(AgentRole.WRITER, `Completed Chapter ${i + 1}.`);
              addLog(AgentRole.REVIEWER, `Verified quality for Chapter ${i + 1}.`);

            } catch (err) {
              addLog(AgentRole.WRITER, `Failed to write Chapter ${i + 1}.`);
              newChapters[i].status = 'error';
              setEBook(prev => ({ ...prev, chapters: [...newChapters] }));
            }
          }
        }

        setStep(WorkflowStep.DESIGN);
      }
    };

    if (step === WorkflowStep.WRITING) {
      processWriting();
    }
  }, [step, eBook.chapters, eBook.title, eBook.targetAudience]);

  // Effect to handle Design Phase
  useEffect(() => {
    const processDesign = async () => {
      if (step === WorkflowStep.DESIGN) {
        addLog(AgentRole.DESIGNER, "Analyzing book themes for cover art...");
        try {
          const imageUrl = await generateCoverImage(eBook.title || "", eBook.description || "");
          setEBook(prev => ({ ...prev, coverImage: imageUrl }));
          addLog(AgentRole.DESIGNER, "Cover image generated successfully.");

          setTimeout(() => {
            setIsProcessing(false);
            setStep(WorkflowStep.COMPLETED);
            addLog(AgentRole.REVIEWER, "Final compilation complete. Ready for download.");
          }, 1000);

        } catch (e) {
            addLog(AgentRole.DESIGNER, "Failed to generate cover.");
            setIsProcessing(false);
            setStep(WorkflowStep.COMPLETED);
        }
      }
    };

    if (step === WorkflowStep.DESIGN) {
      processDesign();
    }
  }, [step, eBook.title, eBook.description]);


  const StepIcon = ({ current, target, icon: Icon }: { current: WorkflowStep, target: WorkflowStep, icon: any }) => {
    const isActive = current === target;
    const isCompleted = current > target;

    return (
      <div className={`flex flex-col items-center z-10 ${isActive ? 'scale-110' : ''} transition-transform`}>
        <div className={`w-12 h-12 rounded-full flex items-center justify-center border-2 
          ${isCompleted ? 'bg-green-500 border-green-500 text-white' : 
            isActive ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg shadow-indigo-200' : 
            'bg-white border-slate-300 text-slate-300'}`}>
          <Icon className="w-6 h-6" />
        </div>
        <span className={`mt-2 text-xs font-semibold ${isActive ? 'text-indigo-600' : isCompleted ? 'text-green-600' : 'text-slate-400'}`}>
           {target === WorkflowStep.OUTLINE && "Strategy"}
           {target === WorkflowStep.WRITING && "Writing"}
           {target === WorkflowStep.DESIGN && "Design"}
           {target === WorkflowStep.COMPLETED && "Done"}
        </span>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans pb-20">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-indigo-600 text-white p-1.5 rounded-lg">
                <SparklesIcon className="w-5 h-5" />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-purple-600">
              SoloPreneur E-Book Architect
            </h1>
          </div>
          <div className="text-sm text-slate-500 hidden sm:block">
            AI Automation Workflow v1.0
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Progress Stepper */}
        {step !== WorkflowStep.INPUT && (
          <div className="mb-10 relative">
            <div className="absolute top-6 left-0 w-full h-0.5 bg-slate-200 -z-0"></div>
            <div className="absolute top-6 left-0 h-0.5 bg-indigo-500 transition-all duration-500 -z-0" 
                 style={{ width: `${(step / 4) * 100}%` }}></div>
            <div className="flex justify-between relative px-10">
               <StepIcon current={step} target={WorkflowStep.OUTLINE} icon={BeakerIcon} />
               <StepIcon current={step} target={WorkflowStep.WRITING} icon={PencilIcon} />
               <StepIcon current={step} target={WorkflowStep.DESIGN} icon={SparklesIcon} />
               <StepIcon current={step} target={WorkflowStep.COMPLETED} icon={BookOpenIcon} />
            </div>
          </div>
        )}

        {step === WorkflowStep.INPUT ? (
          <div className="max-w-2xl mx-auto mt-20">
            <div className="bg-white rounded-2xl shadow-xl border border-slate-100 p-8 text-center">
              <div className="w-16 h-16 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center mx-auto mb-6">
                <SparklesIcon className="w-8 h-8" />
              </div>
              <h2 className="text-3xl font-bold text-slate-900 mb-4">What do you want to write about?</h2>
              <p className="text-slate-600 mb-8">
                Enter a topic, and our team of AI agents will research, outline, write, and design a complete e-book for you in minutes.
              </p>

              <div className="relative">
                <input
                  type="text"
                  value={topic}
                  onChange={(e) => setTopic(e.target.value)}
                  placeholder="e.g., Digital Marketing for Beginners, Healthy Meal Prep..."
                  className="w-full px-6 py-4 text-lg border-2 border-slate-200 rounded-xl focus:border-indigo-500 focus:ring-4 focus:ring-indigo-50/50 outline-none transition-all"
                  onKeyDown={(e) => e.key === 'Enter' && handleStart()}
                />
                <button
                  onClick={handleStart}
                  disabled={!topic.trim() || isProcessing}
                  className="absolute right-2 top-2 bottom-2 bg-indigo-600 text-white px-6 rounded-lg font-medium hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center gap-2"
                >
                  Start Magic <ChevronRightIcon className="w-4 h-4" />
                </button>
              </div>

              <div className="mt-8 flex justify-center gap-6 text-sm text-slate-400">
                <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-purple-400"></span> AI Strategy</span>
                <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-400"></span> Auto-Writing</span>
                <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-pink-400"></span> Cover Design</span>
              </div>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-6">

            {/* Live Status Area */}
            {step !== WorkflowStep.COMPLETED && (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2">
                   <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 min-h-[300px]">
                      <h3 className="font-bold text-lg mb-4 flex items-center gap-2">
                        {step === WorkflowStep.OUTLINE && "Phase 1: Strategic Planning"}
                        {step === WorkflowStep.WRITING && "Phase 2: Content Generation"}
                        {step === WorkflowStep.DESIGN && "Phase 3: Visual Design"}
                      </h3>

                      {eBook.title && (
                         <div className="mb-6 p-4 bg-slate-50 rounded-lg border border-slate-100">
                            <div className="text-xs text-slate-400 uppercase tracking-wider font-semibold mb-1">Working Title</div>
                            <div className="text-xl font-bold text-slate-800">{eBook.title}</div>
                            <div className="text-slate-600 mt-1 text-sm">{eBook.description}</div>
                         </div>
                      )}

                      {/* Chapter Progress Grid */}
                      {eBook.chapters && eBook.chapters.length > 0 && (
                        <div>
                          <div className="text-xs text-slate-400 uppercase tracking-wider font-semibold mb-3">Chapter Progress</div>
                          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                            {eBook.chapters.map((chap, idx) => (
                              <div key={idx} className={`p-3 rounded-lg border flex items-center justify-between ${
                                chap.status === 'completed' ? 'bg-green-50 border-green-200' :
                                chap.status === 'generating' ? 'bg-indigo-50 border-indigo-200 animate-pulse' :
                                'bg-white border-slate-200 opacity-60'
                              }`}>
                                <span className="text-sm font-medium truncate pr-2">
                                  {idx + 1}. {chap.title}
                                </span>
                                {chap.status === 'completed' && <span className="text-xs font-bold text-green-600">DONE</span>}
                                {chap.status === 'generating' && <span className="text-xs font-bold text-indigo-600">WRITING...</span>}
                                {chap.status === 'pending' && <span className="text-xs text-slate-400">WAITING</span>}
                              </div>
                            ))}
                          </div>
                        </div>
                      )}
                   </div>
                </div>

                <div className="lg:col-span-1">
                   <AgentLog logs={logs} />
                </div>
              </div>
            )}

            {/* Final Result View */}
            {step === WorkflowStep.COMPLETED && (
               <BookPreview 
                  ebook={eBook as EBook} 
                  onRestart={() => {
                    setTopic('');
                    setStep(WorkflowStep.INPUT);
                    setEBook({ chapters: [] });
                    setLogs([]);
                  }} 
               />
            )}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

{
  "name": "SoloPreneur AI E-Book Architect",
  "description": "ระบบอัตโนมัติด้วย AI Agent เพื่อสร้าง E-Book แบบครบวงจรจากไอเดียเดียว มีฟีเจอร์สำหรับวางโครงเรื่อง เขียนเนื้อหา และออกแบบปก",
  "requestFramePermissions": []
}

export interface Chapter {
  id: string;
  title: string;
  content?: string;
  status: 'pending' | 'generating' | 'completed' | 'error';
}

export interface EBook {
  topic: string;
  title: string;
  targetAudience: string;
  description: string;
  chapters: Chapter[];
  coverImage?: string;
}

export enum AgentRole {
  STRATEGIST = 'นักวางกลยุทธ์',
  WRITER = 'นักเขียน',
  DESIGNER = 'นักออกแบบ',
  REVIEWER = 'บรรณาธิการ'
}

export interface LogEntry {
  timestamp: Date;
  agent: AgentRole;
  message: string;
}

export enum WorkflowStep {
  INPUT = 0,
  OUTLINE = 1,
  WRITING = 2,
  DESIGN = 3,
  COMPLETED = 4
}

import { GoogleGenAI, Type } from "@google/genai";
import { Chapter, EBook } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("ไม่พบ API Key กรุณาตั้งค่า process.env.API_KEY");
  }
  return new GoogleGenAI({ apiKey });
};

// 1. Agent: Strategist - Creates the Outline
export const generateBookOutline = async (topic: string): Promise<Partial<EBook>> => {
  const ai = getClient();

  const prompt = `
    You are an expert E-Book Strategist and Publisher.
    Your task is to plan a non-fiction e-book based on the user's topic: "${topic}".

    1. Create a catchy Title in Thai language.
    2. Define the Target Audience in Thai language.
    3. Write a short Description in Thai language.
    4. Create an outline with exactly 4 distinct chapters.

    The content MUST be in Thai Language.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          targetAudience: { type: Type.STRING },
          description: { type: Type.STRING },
          chapters: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                summary: { type: Type.STRING } // Helper for the writer later
              },
              required: ["title", "summary"]
            }
          }
        },
        required: ["title", "targetAudience", "description", "chapters"]
      }
    }
  });

  if (!response.text) throw new Error("ไม่สามารถสร้างโครงเรื่องได้");

  const data = JSON.parse(response.text);

  // Transform to our internal Chapter type
  const chapters: Chapter[] = data.chapters.map((c: any, index: number) => ({
    id: `ch-${index}`,
    title: c.title,
    content: '',
    status: 'pending'
  }));

  return {
    title: data.title,
    targetAudience: data.targetAudience,
    description: data.description,
    chapters: chapters
  };
};

// 2. Agent: Writer - Writes a specific chapter
export const generateChapterContent = async (
  bookTitle: string, 
  chapterTitle: string, 
  audience: string
): Promise<string> => {
  const ai = getClient();

  const prompt = `
    You are a professional Ghostwriter.
    Write the content for a chapter in an e-book.

    Book Title: ${bookTitle}
    Target Audience: ${audience}
    Chapter Title: ${chapterTitle}

    Requirements:
    - Language: Thai (Formal but accessible).
    - Length: Approximately 400-500 words.
    - Structure: Use headers, bullet points where appropriate, and a concluding summary.
    - Format: Markdown.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: prompt,
  });

  return response.text || "เกิดข้อผิดพลาดในการสร้างเนื้อหา";
};

// 3. Agent: Designer - Creates the Cover Image
export const generateCoverImage = async (title: string, description: string): Promise<string> => {
  const ai = getClient();

  // First, generate a prompt for the image model based on the book info
  const promptDesignResponse = await ai.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: `Create a highly detailed, artistic image generation prompt for an e-book cover. 
    Book Title: "${title}". 
    Description: "${description}".
    Style: Minimalist, Modern, Professional, High contrast. 
    Output only the English prompt text.`
  });

  const imagePrompt = promptDesignResponse.text || `A professional book cover for ${title}`;

  // Generate the actual image
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview', // Using the advanced image model
      contents: {
        parts: [{ text: imagePrompt }]
      },
      config: {
        imageConfig: {
            aspectRatio: "3:4", // Standard book ratio
            imageSize: "1K"
        }
      }
    });

    // Extract image
    for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
            return `data:image/png;base64,${part.inlineData.data}`;
        }
    }

    throw new Error("ไม่ได้รับข้อมูลรูปภาพกลับมาจาก API");

  } catch (e) {
    console.error("Image gen error", e);
    return "https://picsum.photos/600/800"; // Fallback
  }
};

import React, { useEffect, useRef } from 'react';
import { LogEntry, AgentRole } from '../types';

interface AgentLogProps {
  logs: LogEntry[];
}

const getAgentColor = (role: AgentRole) => {
  switch (role) {
    case AgentRole.STRATEGIST: return 'text-purple-600 bg-purple-100';
    case AgentRole.WRITER: return 'text-blue-600 bg-blue-100';
    case AgentRole.DESIGNER: return 'text-pink-600 bg-pink-100';
    case AgentRole.REVIEWER: return 'text-emerald-600 bg-emerald-100';
    default: return 'text-gray-600 bg-gray-100';
  }
};

export const AgentLog: React.FC<AgentLogProps> = ({ logs }) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [logs]);

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 h-64 flex flex-col overflow-hidden">
      <div className="p-3 bg-slate-50 border-b border-slate-200 font-semibold text-slate-700 flex justify-between items-center">
        <span>บันทึกการทำงานของระบบ</span>
        <span className="text-xs font-normal text-slate-500">สด</span>
      </div>
      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        {logs.length === 0 && (
          <p className="text-center text-slate-400 italic text-sm mt-10">กำลังรอคำสั่ง...</p>
        )}
        {logs.map((log, index) => (
          <div key={index} className="flex gap-3 items-start animate-fade-in">
            <div className="min-w-[4rem] text-xs text-slate-400 mt-1">
              {log.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
            </div>
            <div className="flex-1">
              <span className={`inline-block px-2 py-0.5 rounded text-xs font-bold mr-2 mb-1 ${getAgentColor(log.agent)}`}>
                {log.agent}
              </span>
              <p className="text-sm text-slate-700">{log.message}</p>
            </div>
          </div>
        ))}
        <div ref={bottomRef} />
      </div>
    </div>
  );
};

