                                {chap.status === 'completed' && <span className="text-xs font-bold text-green-600">เสร็จแล้ว</span>}
                                {chap.status === 'generating' && <span className="text-xs font-bold text-indigo-600">กำลังเขียน...</span>}
                                {chap.status === 'pending' && <span className="text-xs text-slate-400">รอคิว</span>}
                              </div>
                            ))}
                          </div>
                        </div>
                      )}

                      {/* Review Status Info */}
                      {step === WorkflowStep.REVIEW && (
                        <div className="mt-6 p-4 bg-emerald-50 border border-emerald-100 rounded-lg animate-pulse flex items-center gap-3">
