                        </div>
                      )}
                   </div>
                </div>

                <div className="lg:col-span-1">
                   <AgentLog logs={logs} />
                </div>
              </div>
            )}

            {/* Final Result View */}
            {step === WorkflowStep.COMPLETED && (
               <BookPreview 
                  ebook={eBook as EBook} 
                  onRestart={() => {
                    setTopic('');
                    setStep(WorkflowStep.INPUT);
                    setEBook({ chapters: [] });
                    setLogs([]);
                  }} 
               />
            )}
          </div>
        )}
      </main>
    </div>
  );
};

