import React, { useState, useEffect, useRef } from 'react';
import { Chapter, EBook, AgentRole, LogEntry, WorkflowStep } from './types';
import { generateBookOutline, generateChapterContent, generateCoverImage } from './services/geminiService';
import { AgentLog } from './components/AgentLog';
import { BookPreview } from './components/BookPreview';
import { 
  BeakerIcon, 
  BookOpenIcon, 
  PencilIcon, 
  SparklesIcon, 
  ChevronRightIcon, 
  UserIcon,
  ArrowRightIcon,
  ClipboardDocumentCheckIcon
} from '@heroicons/react/24/solid';

const COVER_STYLES = ['Minimalist', 'Vibrant', 'Vintage', 'Modern', 'Abstract'];

const App: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [coverStyle, setCoverStyle] = useState<string>('Minimalist');
  const [step, setStep] = useState<WorkflowStep>(WorkflowStep.INPUT);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [eBook, setEBook] = useState<Partial<EBook>>({ chapters: [] });
  const [isProcessing, setIsProcessing] = useState(false);

  const addLog = (agent: AgentRole, message: string) => {
    setLogs(prev => [...prev, { timestamp: new Date(), agent, message }]);
  };

  const handleStart = async () => {
    if (!topic.trim()) return;
    setStep(WorkflowStep.OUTLINE);
    setIsProcessing(true);
    setLogs([]); // Clear previous logs

    try {
      // Step 1: Strategy
      addLog(AgentRole.STRATEGIST, `กำลังวิเคราะห์หัวข้อ: "${topic}"...`);
      addLog(AgentRole.STRATEGIST, "กำลังค้นคว้าแนวโน้มตลาดและกลุ่มเป้าหมาย");

      const outlineData = await generateBookOutline(topic);
      setEBook(outlineData);
      addLog(AgentRole.STRATEGIST, `สร้างโครงร่างสำเร็จ: "${outlineData.title}" ทั้งหมด ${outlineData.chapters?.length} ส่วน (รวมบทสรุป)`);

      // Move to writing automatically
      setTimeout(() => setStep(WorkflowStep.WRITING), 1500);

    } catch (error) {
      addLog(AgentRole.STRATEGIST, `เกิดข้อผิดพลาด: ${(error as Error).message}`);
      setIsProcessing(false);
      setStep(WorkflowStep.INPUT);
    }
  };

  // Effect to handle the Writing Phase
  useEffect(() => {
    const processWriting = async () => {
      if (step === WorkflowStep.WRITING && eBook.chapters && eBook.chapters.length > 0) {

        const newChapters = [...eBook.chapters];

        for (let i = 0; i < newChapters.length; i++) {
          const chapter = newChapters[i];
          if (chapter.status === 'pending') {
            // Update UI to show generating
            newChapters[i].status = 'generating';
            setEBook(prev => ({ ...prev, chapters: [...newChapters] }));

            const isConclusion = chapter.id === 'ch-conclusion';
            const logPrefix = isConclusion ? 'กำลังเขียนบทสรุปส่งท้าย' : `กำลังเริ่มเขียนบทที่ ${i + 1}`;
            addLog(AgentRole.WRITER, `${logPrefix}: ${chapter.title}`);

            try {
              const content = await generateChapterContent(
                eBook.title || "หนังสือ", 
                chapter.title, 
                eBook.targetAudience || "ผู้อ่านทั่วไป",
                eBook.description || ""
              );

              newChapters[i].content = content;
              newChapters[i].status = 'completed';
              setEBook(prev => ({ ...prev, chapters: [...newChapters] }));

              if (isConclusion) {
                addLog(AgentRole.WRITER, `เขียนบทสรุปเสร็จสิ้น`);
              } else {
                addLog(AgentRole.WRITER, `เขียนบทที่ ${i + 1} เสร็จสิ้น`);
              }

            } catch (err) {
              addLog(AgentRole.WRITER, `ไม่สามารถเขียนเนื้อหาได้: ${chapter.title}`);
              newChapters[i].status = 'error';
              setEBook(prev => ({ ...prev, chapters: [...newChapters] }));
            }
          }
        }

        setStep(WorkflowStep.DESIGN);
      }
    };

    if (step === WorkflowStep.WRITING) {
      processWriting();
    }
  }, [step, eBook.chapters, eBook.title, eBook.targetAudience, eBook.description]);

  // Effect to handle Design Phase
  useEffect(() => {
    const processDesign = async () => {
      if (step === WorkflowStep.DESIGN) {
        addLog(AgentRole.DESIGNER, `กำลังวิเคราะห์ธีมของหนังสือเพื่อออกแบบปกสไตล์ ${coverStyle}...`);
        try {
          const imageUrl = await generateCoverImage(eBook.title || "", eBook.description || "", coverStyle);
          setEBook(prev => ({ ...prev, coverImage: imageUrl }));
          addLog(AgentRole.DESIGNER, "สร้างรูปปกสำเร็จแล้ว");

          setTimeout(() => {
             setStep(WorkflowStep.REVIEW);
          }, 1000);

        } catch (e) {
            addLog(AgentRole.DESIGNER, "ไม่สามารถสร้างปกได้");
            setStep(WorkflowStep.REVIEW);
        }
      }
    };

    if (step === WorkflowStep.DESIGN) {
      processDesign();
    }
  }, [step, eBook.title, eBook.description, coverStyle]);

  // Effect to handle Review Phase
  useEffect(() => {
    const processReview = async () => {
        if (step === WorkflowStep.REVIEW) {
            addLog(AgentRole.REVIEWER, "เริ่มตรวจสอบความถูกต้องของเนื้อหาและรูปแบบ (Final Review)...");

            // Simulate review process for chapters
            const chapterCount = eBook.chapters?.length || 0;
            for (let i = 0; i < chapterCount; i++) {
                await new Promise(r => setTimeout(r, 600)); 
                const chap = eBook.chapters?.[i];
                const isConclusion = chap?.id === 'ch-conclusion';

                addLog(AgentRole.REVIEWER, isConclusion ? `กำลังตรวจทานบทสรุป...` : `กำลังตรวจทานบทที่ ${i + 1}...`);

                await new Promise(r => setTimeout(r, 400));
                // Randomly add a "fixing" log to make it realistic
                if (Math.random() > 0.7) {
                    addLog(AgentRole.REVIEWER, `แก้ไขคำผิดและปรับสำนวนใน${isConclusion ? 'บทสรุป' : `บทที่ ${i + 1}`}`);
                }
                addLog(AgentRole.REVIEWER, `${isConclusion ? 'บทสรุป' : `บทที่ ${i + 1}`} ผ่านเกณฑ์คุณภาพ`);
            }

            // Check cover
            await new Promise(r => setTimeout(r, 600));
            addLog(AgentRole.REVIEWER, "ตรวจสอบความเข้ากันของภาพปกและเนื้อหา...");
            await new Promise(r => setTimeout(r, 400));
            addLog(AgentRole.REVIEWER, "อนุมัติการออกแบบ");

            addLog(AgentRole.REVIEWER, "การตรวจสอบเสร็จสิ้น พร้อมส่งมอบผลงาน");
            setTimeout(() => {
                setIsProcessing(false);
                setStep(WorkflowStep.COMPLETED);
            }, 800);
        }
    }

    if (step === WorkflowStep.REVIEW) {
        processReview();
    }
  }, [step, eBook.chapters]);


  const StepIcon = ({ current, target, icon: Icon }: { current: WorkflowStep, target: WorkflowStep, icon: any }) => {
    const isActive = current === target;
    const isCompleted = current > target;

    return (
      <div className={`flex flex-col items-center z-10 ${isActive ? 'scale-110' : ''} transition-transform`}>
        <div className={`w-12 h-12 rounded-full flex items-center justify-center border-2 
          ${isCompleted ? 'bg-green-500 border-green-500 text-white' : 
            isActive ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg shadow-indigo-200' : 
            'bg-white border-slate-300 text-slate-300'}`}>
          <Icon className="w-6 h-6" />
        </div>
        <span className={`mt-2 text-xs font-semibold ${isActive ? 'text-indigo-600' : isCompleted ? 'text-green-600' : 'text-slate-400'}`}>
           {target === WorkflowStep.OUTLINE && "วางกลยุทธ์"}
           {target === WorkflowStep.WRITING && "เขียนเนื้อหา"}
           {target === WorkflowStep.DESIGN && "ออกแบบปก"}
           {target === WorkflowStep.REVIEW && "ตรวจสอบ"}
           {target === WorkflowStep.COMPLETED && "เสร็จสิ้น"}
        </span>
      </div>
    );
  };

  const WorkflowFlowchart = () => (
    <div className="mt-16 border-t border-slate-100 pt-10 animate-fade-in">
      <h3 className="text-center text-slate-400 font-semibold uppercase tracking-wider text-xs mb-8">
        เบื้องหลังการทำงาน (AI Workflow Diagram)
      </h3>

      <div className="flex flex-col md:flex-row justify-center items-center gap-6 md:gap-2 relative max-w-6xl mx-auto">
        {/* Connecting Line Desktop */}
        <div className="hidden md:block absolute top-[28px] left-12 right-12 h-0.5 bg-gradient-to-r from-slate-200 via-indigo-200 to-slate-200 -z-10"></div>

        {/* Node 1: User */}
        <div className="flex flex-col items-center group w-32 md:w-36">
          <div className="w-14 h-14 bg-white border-2 border-slate-300 text-slate-600 rounded-2xl flex items-center justify-center shadow-sm mb-3 relative z-10 transition-transform group-hover:scale-110">
            <UserIcon className="w-7 h-7" />
          </div>
          <div className="font-bold text-slate-700 text-sm">1. คุณ (Input)</div>
          <div className="text-xs text-slate-500 text-center mt-1">ป้อนหัวข้อ</div>
          <div className="md:hidden mt-2 text-slate-300"><ArrowRightIcon className="w-4 h-4 rotate-90" /></div>
        </div>

        {/* Node 2: Strategist */}
        <div className="flex flex-col items-center group w-32 md:w-36">
          <div className="w-14 h-14 bg-purple-50 border-2 border-purple-200 text-purple-600 rounded-2xl flex items-center justify-center shadow-sm mb-3 relative z-10 transition-transform group-hover:scale-110">
            <BeakerIcon className="w-7 h-7" />
          </div>
          <div className="font-bold text-purple-900 text-sm">2. นักวางกลยุทธ์</div>
          <div className="text-xs text-slate-500 text-center mt-1">วางโครงเรื่อง</div>
          <div className="md:hidden mt-2 text-slate-300"><ArrowRightIcon className="w-4 h-4 rotate-90" /></div>
        </div>

        {/* Node 3: Writer */}
        <div className="flex flex-col items-center group w-32 md:w-36">
          <div className="w-14 h-14 bg-blue-50 border-2 border-blue-200 text-blue-600 rounded-2xl flex items-center justify-center shadow-sm mb-3 relative z-10 transition-transform group-hover:scale-110">
            <PencilIcon className="w-7 h-7" />
          </div>
          <div className="font-bold text-blue-900 text-sm">3. นักเขียน</div>
          <div className="text-xs text-slate-500 text-center mt-1">เขียนเนื้อหา</div>
          <div className="md:hidden mt-2 text-slate-300"><ArrowRightIcon className="w-4 h-4 rotate-90" /></div>
        </div>

        {/* Node 4: Designer */}
        <div className="flex flex-col items-center group w-32 md:w-36">
          <div className="w-14 h-14 bg-pink-50 border-2 border-pink-200 text-pink-600 rounded-2xl flex items-center justify-center shadow-sm mb-3 relative z-10 transition-transform group-hover:scale-110">
            <SparklesIcon className="w-7 h-7" />
          </div>
          <div className="font-bold text-pink-900 text-sm">4. นักออกแบบ</div>
          <div className="text-xs text-slate-500 text-center mt-1">สร้างปก</div>
          <div className="md:hidden mt-2 text-slate-300"><ArrowRightIcon className="w-4 h-4 rotate-90" /></div>
        </div>

        {/* Node 5: Reviewer */}
        <div className="flex flex-col items-center group w-32 md:w-36">
          <div className="w-14 h-14 bg-emerald-50 border-2 border-emerald-200 text-emerald-600 rounded-2xl flex items-center justify-center shadow-sm mb-3 relative z-10 transition-transform group-hover:scale-110">
            <ClipboardDocumentCheckIcon className="w-7 h-7" />
          </div>
          <div className="font-bold text-emerald-900 text-sm">5. บรรณาธิการ</div>
          <div className="text-xs text-slate-500 text-center mt-1">ตรวจทาน</div>
          <div className="md:hidden mt-2 text-slate-300"><ArrowRightIcon className="w-4 h-4 rotate-90" /></div>
        </div>

         {/* Node 6: Output */}
        <div className="flex flex-col items-center group w-32 md:w-36">
          <div className="w-14 h-14 bg-green-100 border-2 border-green-300 text-green-700 rounded-2xl flex items-center justify-center shadow-sm mb-3 relative z-10 transition-transform group-hover:scale-110">
            <BookOpenIcon className="w-7 h-7" />
          </div>
          <div className="font-bold text-green-900 text-sm">6. E-Book</div>
          <div className="text-xs text-slate-500 text-center mt-1">พร้อมใช้งาน</div>
        </div>

      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans pb-20">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-indigo-600 text-white p-1.5 rounded-lg">
                <SparklesIcon className="w-5 h-5" />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-purple-600">
              SoloPreneur E-Book Architect
            </h1>
          </div>
          <div className="text-sm text-slate-500 hidden sm:block">
            ระบบสร้าง E-Book อัตโนมัติด้วย AI v1.0
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Progress Stepper */}
        {step !== WorkflowStep.INPUT && (
          <div className="mb-10 relative">
            <div className="absolute top-6 left-0 w-full h-0.5 bg-slate-200 -z-0"></div>
            <div className="absolute top-6 left-0 h-0.5 bg-indigo-500 transition-all duration-500 -z-0" 
                 style={{ width: `${(step / 5) * 100}%` }}></div>
            <div className="flex justify-between relative px-4 sm:px-10">
               <StepIcon current={step} target={WorkflowStep.OUTLINE} icon={BeakerIcon} />
               <StepIcon current={step} target={WorkflowStep.WRITING} icon={PencilIcon} />
               <StepIcon current={step} target={WorkflowStep.DESIGN} icon={SparklesIcon} />
               <StepIcon current={step} target={WorkflowStep.REVIEW} icon={ClipboardDocumentCheckIcon} />
               <StepIcon current={step} target={WorkflowStep.COMPLETED} icon={BookOpenIcon} />
            </div>
          </div>
        )}

        {step === WorkflowStep.INPUT ? (
          <div className="max-w-4xl mx-auto mt-10">
            <div className="bg-white rounded-2xl shadow-xl border border-slate-100 p-10 text-center">
              <div className="w-16 h-16 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center mx-auto mb-6">
                <SparklesIcon className="w-8 h-8" />
              </div>
              <h2 className="text-3xl font-bold text-slate-900 mb-4">คุณต้องการเขียนเรื่องอะไร?</h2>
              <p className="text-slate-600 mb-8 max-w-lg mx-auto">
                ระบุหัวข้อที่คุณสนใจ แล้วทีม AI ของเราจะทำการค้นคว้า วางโครงเรื่อง เขียนเนื้อหา และออกแบบปกให้คุณภายในไม่กี่นาที
              </p>

              <div className="relative max-w-xl mx-auto">
                <input
                  type="text"
                  value={topic}
                  onChange={(e) => setTopic(e.target.value)}
                  placeholder="เช่น การตลาดออนไลน์สำหรับมือใหม่, สูตรอาหารคลีนทำง่าย..."
                  className="w-full px-6 py-4 text-lg border-2 border-slate-200 rounded-xl focus:border-indigo-500 focus:ring-4 focus:ring-indigo-50/50 outline-none transition-all pr-36"
                  onKeyDown={(e) => e.key === 'Enter' && handleStart()}
                />
                <button
                  onClick={handleStart}
                  disabled={!topic.trim() || isProcessing}
                  className="absolute right-2 top-2 bottom-2 bg-indigo-600 text-white px-6 rounded-lg font-medium hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center gap-2"
                >
                  เริ่มสร้างทันที <ChevronRightIcon className="w-4 h-4" />
                </button>
              </div>

              {/* Cover Style Selector */}
              <div className="mt-8">
                <p className="text-slate-500 mb-3 text-sm font-medium">เลือกสไตล์ปก (Cover Style)</p>
                <div className="flex flex-wrap justify-center gap-3">
                  {COVER_STYLES.map((style) => (
                    <button
                      key={style}
                      onClick={() => setCoverStyle(style)}
                      className={`px-4 py-2 rounded-full text-sm font-medium transition-all ${
                        coverStyle === style
                          ? 'bg-indigo-600 text-white shadow-md shadow-indigo-200 ring-2 ring-indigo-100'
                          : 'bg-white border border-slate-200 text-slate-600 hover:border-indigo-300 hover:text-indigo-600'
                      }`}
                    >
                      {style}
                    </button>
                  ))}
                </div>
              </div>

            </div>

            {/* AI Workflow Flowchart Diagram */}
            <WorkflowFlowchart />
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-6">

            {/* Live Status Area */}
            {step !== WorkflowStep.COMPLETED && (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2">
                   <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 min-h-[300px]">
                      <h3 className="font-bold text-lg mb-4 flex items-center gap-2">
                        {step === WorkflowStep.OUTLINE && "ระยะที่ 1: การวางแผนกลยุทธ์"}
                        {step === WorkflowStep.WRITING && "ระยะที่ 2: การสร้างเนื้อหา"}
                        {step === WorkflowStep.DESIGN && "ระยะที่ 3: การออกแบบภาพลักษณ์"}
                        {step === WorkflowStep.REVIEW && "ระยะที่ 4: การตรวจสอบคุณภาพ (QC)"}
                      </h3>

                      {eBook.title && (
                         <div className="mb-6 p-4 bg-slate-50 rounded-lg border border-slate-100">
                            <div className="text-xs text-slate-400 uppercase tracking-wider font-semibold mb-1">ชื่อเรื่องชั่วคราว</div>
                            <div className="text-xl font-bold text-slate-800">{eBook.title}</div>
                            <div className="text-slate-600 mt-1 text-sm">{eBook.description}</div>
                         </div>
                      )}

                      {/* Chapter Progress Grid */}
                      {eBook.chapters && eBook.chapters.length > 0 && (
                        <div>
                          <div className="text-xs text-slate-400 uppercase tracking-wider font-semibold mb-3">ความคืบหน้าของเนื้อหา</div>
                          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                            {eBook.chapters.map((chap, idx) => (
                              <div key={idx} className={`p-3 rounded-lg border flex items-center justify-between ${
                                chap.status === 'completed' ? 'bg-green-50 border-green-200' :
                                chap.status === 'generating' ? 'bg-indigo-50 border-indigo-200 animate-pulse' :
                                'bg-white border-slate-200 opacity-60'
                              }`}>
                                <span className="text-sm font-medium truncate pr-2">
                                  {chap.id === 'ch-conclusion' ? 'บทส่งท้าย' : `${idx + 1}.`} {chap.title}
                                </span>
                                {chap.status === 'completed' && <span className="text-xs font-bold text-green-600">เสร็จแล้ว</span>}
                                {chap.status === 'generating' && <span className="text-xs font-bold text-indigo-600">กำลังเขียน...</span>}
                                {chap.status === 'pending' && <span className="text-xs text-slate-400">รอคิว</span>}
                              </div>
                            ))}
                          </div>
                        </div>
                      )}

                      {/* Review Status Info */}
                      {step === WorkflowStep.REVIEW && (
                        <div className="mt-6 p-4 bg-emerald-50 border border-emerald-100 rounded-lg animate-pulse flex items-center gap-3">
                           <ClipboardDocumentCheckIcon className="w-6 h-6 text-emerald-600" />
                           <span className="text-emerald-800 font-medium">บรรณาธิการกำลังตรวจทานผลงานของคุณ...</span>
                        </div>
                      )}
                   </div>
                </div>

                <div className="lg:col-span-1">
                   <AgentLog logs={logs} />
                </div>
              </div>
            )}

            {/* Final Result View */}
            {step === WorkflowStep.COMPLETED && (
               <BookPreview 
                  ebook={eBook as EBook} 
                  onRestart={() => {
                    setTopic('');
                    setStep(WorkflowStep.INPUT);
                    setEBook({ chapters: [] });
                    setLogs([]);
                    setCoverStyle('Minimalist');
                  }} 
               />
            )}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

export interface Chapter {
  id: string;
  title: string;
  content?: string;
  status: 'pending' | 'generating' | 'completed' | 'error';
}

export interface EBook {
  topic: string;
  title: string;
  targetAudience: string;
  description: string;
  chapters: Chapter[];
  coverImage?: string;
  coverStyle?: string;
}

export enum AgentRole {
  STRATEGIST = 'นักวางกลยุทธ์',
  WRITER = 'นักเขียน',
  DESIGNER = 'นักออกแบบ',
  REVIEWER = 'บรรณาธิการ'
}

export interface LogEntry {
  timestamp: Date;
  agent: AgentRole;
  message: string;
}

export enum WorkflowStep {
  INPUT = 0,
  OUTLINE = 1,
  WRITING = 2,
  DESIGN = 3,
  REVIEW = 4,
  COMPLETED = 5
}

import React, { useState, useEffect, useRef } from 'react';
import { Chapter, EBook, AgentRole, LogEntry, WorkflowStep } from './types';
import { generateBookOutline, generateChapterContent, generateCoverImage } from './services/geminiService';
import { AgentLog } from './components/AgentLog';
import { BookPreview } from './components/BookPreview';
import { 
  BeakerIcon, 
  BookOpenIcon, 
  PencilIcon, 
  SparklesIcon, 
  ChevronRightIcon, 
  UserIcon,
  ArrowRightIcon,
  ClipboardDocumentCheckIcon
} from '@heroicons/react/24/solid';

const COVER_STYLES = ['Minimalist', 'Vibrant', 'Vintage', 'Modern', 'Abstract', 'Futuristic', 'Geometric', 'Corporate'];

const App: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [coverStyle, setCoverStyle] = useState<string>('Minimalist');
  const [step, setStep] = useState<WorkflowStep>(WorkflowStep.INPUT);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [eBook, setEBook] = useState<Partial<EBook>>({ chapters: [] });
  const [isProcessing, setIsProcessing] = useState(false);

  const addLog = (agent: AgentRole, message: string) => {
    setLogs(prev => [...prev, { timestamp: new Date(), agent, message }]);
  };

  const handleStart = async () => {
    if (!topic.trim()) return;
    setStep(WorkflowStep.OUTLINE);
    setIsProcessing(true);
    setLogs([]); // Clear previous logs

    try {
      // Step 1: Strategy
      addLog(AgentRole.STRATEGIST, `กำลังวิเคราะห์หัวข้อ: "${topic}"...`);
      addLog(AgentRole.STRATEGIST, "กำลังค้นคว้าแนวโน้มตลาดและกลุ่มเป้าหมาย");

      const outlineData = await generateBookOutline(topic);
      // Persist the selected cover style into the ebook object
      setEBook({ ...outlineData, coverStyle });

      addLog(AgentRole.STRATEGIST, `สร้างโครงร่างสำเร็จ: "${outlineData.title}" ทั้งหมด ${outlineData.chapters?.length} ส่วน (รวมบทสรุป)`);

      // Move to writing automatically
      setTimeout(() => setStep(WorkflowStep.WRITING), 1500);

    } catch (error) {
      addLog(AgentRole.STRATEGIST, `เกิดข้อผิดพลาด: ${(error as Error).message}`);
      setIsProcessing(false);
      setStep(WorkflowStep.INPUT);
    }
  };

  // Effect to handle the Writing Phase
  useEffect(() => {
    const processWriting = async () => {
      if (step === WorkflowStep.WRITING && eBook.chapters && eBook.chapters.length > 0) {

        const newChapters = [...eBook.chapters];

        for (let i = 0; i < newChapters.length; i++) {
          const chapter = newChapters[i];
          if (chapter.status === 'pending') {
            // Update UI to show generating
            newChapters[i].status = 'generating';
            setEBook(prev => ({ ...prev, chapters: [...newChapters] }));

            const isConclusion = chapter.id === 'ch-conclusion';
            const logPrefix = isConclusion ? 'กำลังเขียนบทสรุปส่งท้าย' : `กำลังเริ่มเขียนบทที่ ${i + 1}`;
            addLog(AgentRole.WRITER, `${logPrefix}: ${chapter.title}`);

            try {
              const content = await generateChapterContent(
                eBook.title || "หนังสือ", 
                chapter.title, 
                eBook.targetAudience || "ผู้อ่านทั่วไป",
                eBook.description || ""
              );

              newChapters[i].content = content;
              newChapters[i].status = 'completed';
              setEBook(prev => ({ ...prev, chapters: [...newChapters] }));

              if (isConclusion) {
                addLog(AgentRole.WRITER, `เขียนบทสรุปเสร็จสิ้น`);
              } else {
                addLog(AgentRole.WRITER, `เขียนบทที่ ${i + 1} เสร็จสิ้น`);
              }

            } catch (err) {
              addLog(AgentRole.WRITER, `ไม่สามารถเขียนเนื้อหาได้: ${chapter.title}`);
              newChapters[i].status = 'error';
              setEBook(prev => ({ ...prev, chapters: [...newChapters] }));
            }
          }
        }

        setStep(WorkflowStep.DESIGN);
      }
    };

    if (step === WorkflowStep.WRITING) {
      processWriting();
    }
  }, [step, eBook.chapters, eBook.title, eBook.targetAudience, eBook.description]);

  // Effect to handle Design Phase
  useEffect(() => {
    const processDesign = async () => {
      if (step === WorkflowStep.DESIGN) {
        const styleToUse = eBook.coverStyle || coverStyle; // Use persisted style or current state
        addLog(AgentRole.DESIGNER, `กำลังวิเคราะห์ธีมของหนังสือเพื่อออกแบบปกสไตล์ ${styleToUse}...`);
        try {
          const imageUrl = await generateCoverImage(eBook.title || "", eBook.description || "", styleToUse);
          setEBook(prev => ({ ...prev, coverImage: imageUrl }));
          addLog(AgentRole.DESIGNER, "สร้างรูปปกสำเร็จแล้ว");

          setTimeout(() => {
             setStep(WorkflowStep.REVIEW);
          }, 1000);

        } catch (e) {
            addLog(AgentRole.DESIGNER, "ไม่สามารถสร้างปกได้");
            setStep(WorkflowStep.REVIEW);
        }
      }
    };

    if (step === WorkflowStep.DESIGN) {
      processDesign();
    }
  }, [step, eBook.title, eBook.description, eBook.coverStyle, coverStyle]);

  // Effect to handle Review Phase
  useEffect(() => {
    const processReview = async () => {
        if (step === WorkflowStep.REVIEW) {
            addLog(AgentRole.REVIEWER, "เริ่มตรวจสอบความถูกต้องของเนื้อหาและรูปแบบ (Final Review)...");

            // Simulate review process for chapters
            const chapterCount = eBook.chapters?.length || 0;
            for (let i = 0; i < chapterCount; i++) {
                await new Promise(r => setTimeout(r, 600)); 
                const chap = eBook.chapters?.[i];
                const isConclusion = chap?.id === 'ch-conclusion';

                addLog(AgentRole.REVIEWER, isConclusion ? `กำลังตรวจทานบทสรุป...` : `กำลังตรวจทานบทที่ ${i + 1}...`);

                await new Promise(r => setTimeout(r, 400));
                // Randomly add a "fixing" log to make it realistic
                if (Math.random() > 0.7) {
                    addLog(AgentRole.REVIEWER, `แก้ไขคำผิดและปรับสำนวนใน${isConclusion ? 'บทสรุป' : `บทที่ ${i + 1}`}`);
                }
                addLog(AgentRole.REVIEWER, `${isConclusion ? 'บทสรุป' : `บทที่ ${i + 1}`} ผ่านเกณฑ์คุณภาพ`);
            }

            // Check cover
            await new Promise(r => setTimeout(r, 600));
            addLog(AgentRole.REVIEWER, "ตรวจสอบความเข้ากันของภาพปกและเนื้อหา...");
            await new Promise(r => setTimeout(r, 400));
            addLog(AgentRole.REVIEWER, "อนุมัติการออกแบบ");

            addLog(AgentRole.REVIEWER, "การตรวจสอบเสร็จสิ้น พร้อมส่งมอบผลงาน");
            setTimeout(() => {
                setIsProcessing(false);
                setStep(WorkflowStep.COMPLETED);
            }, 800);
        }
    }

    if (step === WorkflowStep.REVIEW) {
        processReview();
    }
  }, [step, eBook.chapters]);


  const StepIcon = ({ current, target, icon: Icon }: { current: WorkflowStep, target: WorkflowStep, icon: any }) => {
    const isActive = current === target;
    const isCompleted = current > target;

    return (
      <div className={`flex flex-col items-center z-10 ${isActive ? 'scale-110' : ''} transition-transform`}>
        <div className={`w-12 h-12 rounded-full flex items-center justify-center border-2 
          ${isCompleted ? 'bg-green-500 border-green-500 text-white' : 
            isActive ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg shadow-indigo-200' : 
            'bg-white border-slate-300 text-slate-300'}`}>
          <Icon className="w-6 h-6" />
        </div>
        <span className={`mt-2 text-xs font-semibold ${isActive ? 'text-indigo-600' : isCompleted ? 'text-green-600' : 'text-slate-400'}`}>
           {target === WorkflowStep.OUTLINE && "วางกลยุทธ์"}
           {target === WorkflowStep.WRITING && "เขียนเนื้อหา"}
           {target === WorkflowStep.DESIGN && "ออกแบบปก"}
           {target === WorkflowStep.REVIEW && "ตรวจสอบ"}
           {target === WorkflowStep.COMPLETED && "เสร็จสิ้น"}
        </span>
      </div>
    );
  };

  const WorkflowFlowchart = () => (
    <div className="mt-16 border-t border-slate-100 pt-10 animate-fade-in">
      <h3 className="text-center text-slate-400 font-semibold uppercase tracking-wider text-xs mb-8">
        เบื้องหลังการทำงาน (AI Workflow Diagram)
      </h3>

      <div className="flex flex-col md:flex-row justify-center items-center gap-6 md:gap-2 relative max-w-6xl mx-auto">
        {/* Connecting Line Desktop */}
        <div className="hidden md:block absolute top-[28px] left-12 right-12 h-0.5 bg-gradient-to-r from-slate-200 via-indigo-200 to-slate-200 -z-10"></div>

        {/* Node 1: User */}
        <div className="flex flex-col items-center group w-32 md:w-36">
          <div className="w-14 h-14 bg-white border-2 border-slate-300 text-slate-600 rounded-2xl flex items-center justify-center shadow-sm mb-3 relative z-10 transition-transform group-hover:scale-110">
            <UserIcon className="w-7 h-7" />
          </div>
          <div className="font-bold text-slate-700 text-sm">1. คุณ (Input)</div>
          <div className="text-xs text-slate-500 text-center mt-1">ป้อนหัวข้อ</div>
          <div className="md:hidden mt-2 text-slate-300"><ArrowRightIcon className="w-4 h-4 rotate-90" /></div>
        </div>

        {/* Node 2: Strategist */}
        <div className="flex flex-col items-center group w-32 md:w-36">
          <div className="w-14 h-14 bg-purple-50 border-2 border-purple-200 text-purple-600 rounded-2xl flex items-center justify-center shadow-sm mb-3 relative z-10 transition-transform group-hover:scale-110">
            <BeakerIcon className="w-7 h-7" />
          </div>
          <div className="font-bold text-purple-900 text-sm">2. นักวางกลยุทธ์</div>
          <div className="text-xs text-slate-500 text-center mt-1">วางโครงเรื่อง</div>
          <div className="md:hidden mt-2 text-slate-300"><ArrowRightIcon className="w-4 h-4 rotate-90" /></div>
        </div>

        {/* Node 3: Writer */}
        <div className="flex flex-col items-center group w-32 md:w-36">
          <div className="w-14 h-14 bg-blue-50 border-2 border-blue-200 text-blue-600 rounded-2xl flex items-center justify-center shadow-sm mb-3 relative z-10 transition-transform group-hover:scale-110">
            <PencilIcon className="w-7 h-7" />
          </div>
          <div className="font-bold text-blue-900 text-sm">3. นักเขียน</div>
          <div className="text-xs text-slate-500 text-center mt-1">เขียนเนื้อหา</div>
          <div className="md:hidden mt-2 text-slate-300"><ArrowRightIcon className="w-4 h-4 rotate-90" /></div>
        </div>

        {/* Node 4: Designer */}
        <div className="flex flex-col items-center group w-32 md:w-36">
          <div className="w-14 h-14 bg-pink-50 border-2 border-pink-200 text-pink-600 rounded-2xl flex items-center justify-center shadow-sm mb-3 relative z-10 transition-transform group-hover:scale-110">
            <SparklesIcon className="w-7 h-7" />
          </div>
          <div className="font-bold text-pink-900 text-sm">4. นักออกแบบ</div>
          <div className="text-xs text-slate-500 text-center mt-1">สร้างปก</div>
          <div className="md:hidden mt-2 text-slate-300"><ArrowRightIcon className="w-4 h-4 rotate-90" /></div>
        </div>

        {/* Node 5: Reviewer */}
        <div className="flex flex-col items-center group w-32 md:w-36">
          <div className="w-14 h-14 bg-emerald-50 border-2 border-emerald-200 text-emerald-600 rounded-2xl flex items-center justify-center shadow-sm mb-3 relative z-10 transition-transform group-hover:scale-110">
            <ClipboardDocumentCheckIcon className="w-7 h-7" />
          </div>
          <div className="font-bold text-emerald-900 text-sm">5. บรรณาธิการ</div>
          <div className="text-xs text-slate-500 text-center mt-1">ตรวจทาน</div>
          <div className="md:hidden mt-2 text-slate-300"><ArrowRightIcon className="w-4 h-4 rotate-90" /></div>
        </div>

         {/* Node 6: Output */}
        <div className="flex flex-col items-center group w-32 md:w-36">
          <div className="w-14 h-14 bg-green-100 border-2 border-green-300 text-green-700 rounded-2xl flex items-center justify-center shadow-sm mb-3 relative z-10 transition-transform group-hover:scale-110">
            <BookOpenIcon className="w-7 h-7" />
          </div>
          <div className="font-bold text-green-900 text-sm">6. E-Book</div>
          <div className="text-xs text-slate-500 text-center mt-1">พร้อมใช้งาน</div>
        </div>

      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans pb-20">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-indigo-600 text-white p-1.5 rounded-lg">
                <SparklesIcon className="w-5 h-5" />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-purple-600">
              SoloPreneur E-Book Architect
            </h1>
          </div>
          <div className="text-sm text-slate-500 hidden sm:block">
            ระบบสร้าง E-Book อัตโนมัติด้วย AI v1.0
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Progress Stepper */}
        {step !== WorkflowStep.INPUT && (
          <div className="mb-10 relative">
            <div className="absolute top-6 left-0 w-full h-0.5 bg-slate-200 -z-0"></div>
            <div className="absolute top-6 left-0 h-0.5 bg-indigo-500 transition-all duration-500 -z-0" 
                 style={{ width: `${(step / 5) * 100}%` }}></div>
            <div className="flex justify-between relative px-4 sm:px-10">
               <StepIcon current={step} target={WorkflowStep.OUTLINE} icon={BeakerIcon} />
               <StepIcon current={step} target={WorkflowStep.WRITING} icon={PencilIcon} />
               <StepIcon current={step} target={WorkflowStep.DESIGN} icon={SparklesIcon} />
               <StepIcon current={step} target={WorkflowStep.REVIEW} icon={ClipboardDocumentCheckIcon} />
               <StepIcon current={step} target={WorkflowStep.COMPLETED} icon={BookOpenIcon} />
            </div>
          </div>
        )}

        {step === WorkflowStep.INPUT ? (
          <div className="max-w-4xl mx-auto mt-10">
            <div className="bg-white rounded-2xl shadow-xl border border-slate-100 p-10 text-center">
              <div className="w-16 h-16 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center mx-auto mb-6">
                <SparklesIcon className="w-8 h-8" />
              </div>
              <h2 className="text-3xl font-bold text-slate-900 mb-4">คุณต้องการเขียนเรื่องอะไร?</h2>
