              </p>

              <div className="relative max-w-xl mx-auto">
                <input
                  type="text"
                  value={topic}
                  onChange={(e) => setTopic(e.target.value)}
                  placeholder="เช่น การตลาดออนไลน์สำหรับมือใหม่, สูตรอาหารคลีนทำง่าย..."
                  className="w-full px-6 py-4 text-lg border-2 border-slate-200 rounded-xl focus:border-indigo-500 focus:ring-4 focus:ring-indigo-50/50 outline-none transition-all pr-36"
                  onKeyDown={(e) => e.key === 'Enter' && handleStart()}
                />
                <button
                  onClick={handleStart}
                  disabled={!topic.trim() || isProcessing}
                  className="absolute right-2 top-2 bottom-2 bg-indigo-600 text-white px-6 rounded-lg font-medium hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center gap-2"
                >
                  เริ่มสร้างทันที <ChevronRightIcon className="w-4 h-4" />
                </button>
              </div>

              {/* Cover Style Selector */}
              <div className="mt-8">
                <p className="text-slate-500 mb-3 text-sm font-medium">เลือกสไตล์ปก (Cover Style)</p>
                <div className="flex flex-wrap justify-center gap-3">
                  {COVER_STYLES.map((style) => (
                    <button
                      key={style}
                      onClick={() => setCoverStyle(style)}
                      className={`px-4 py-2 rounded-full text-sm font-medium transition-all ${
                        coverStyle === style
                          ? 'bg-indigo-600 text-white shadow-md shadow-indigo-200 ring-2 ring-indigo-100'
                          : 'bg-white border border-slate-200 text-slate-600 hover:border-indigo-300 hover:text-indigo-600'
                      }`}
                    >
                      {style}
                    </button>
                  ))}
                </div>
              </div>

            </div>

            {/* AI Workflow Flowchart Diagram */}
            <WorkflowFlowchart />
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-6">

            {/* Live Status Area */}
            {step !== WorkflowStep.COMPLETED && (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2">
                   <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 min-h-[300px]">
                      <h3 className="font-bold text-lg mb-4 flex items-center gap-2">
                        {step === WorkflowStep.OUTLINE && "ระยะที่ 1: การวางแผนกลยุทธ์"}
                        {step === WorkflowStep.WRITING && "ระยะที่ 2: การสร้างเนื้อหา"}
                        {step === WorkflowStep.DESIGN && "ระยะที่ 3: การออกแบบภาพลักษณ์"}
                        {step === WorkflowStep.REVIEW && "ระยะที่ 4: การตรวจสอบคุณภาพ (QC)"}
                      </h3>

                      {eBook.title && (
                         <div className="mb-6 p-4 bg-slate-50 rounded-lg border border-slate-100">
                            <div className="text-xs text-slate-400 uppercase tracking-wider font-semibold mb-1">ชื่อเรื่องชั่วคราว</div>
                            <div className="text-xl font-bold text-slate-800">{eBook.title}</div>
                            <div className="text-slate-600 mt-1 text-sm">{eBook.description}</div>
                         </div>
                      )}

                      {/* Chapter Progress Grid */}
                      {eBook.chapters && eBook.chapters.length > 0 && (
                        <div>
                          <div className="text-xs text-slate-400 uppercase tracking-wider font-semibold mb-3">ความคืบหน้าของเนื้อหา</div>
                          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                            {eBook.chapters.map((chap, idx) => (
                              <div key={idx} className={`p-3 rounded-lg border flex items-center justify-between ${
                                chap.status === 'completed' ? 'bg-green-50 border-green-200' :
                                chap.status === 'generating' ? 'bg-indigo-50 border-indigo-200 animate-pulse' :
                                'bg-white border-slate-200 opacity-60'
                              }`}>
                                <span className="text-sm font-medium truncate pr-2">
                                  {chap.id === 'ch-conclusion' ? 'บทส่งท้าย' : `${idx + 1}.`} {chap.title}
                                </span>
                                {chap.status === 'completed' && <span className="text-xs font-bold text-green-600">เสร็จแล้ว</span>}
                                {chap.status === 'generating' && <span className="text-xs font-bold text-indigo-600">กำลังเขียน...</span>}
                                {chap.status === 'pending' && <span className="text-xs text-slate-400">รอคิว</span>}
                              </div>
                            ))}
                          </div>
                        </div>
                      )}

                      {/* Review Status Info */}
                      {step === WorkflowStep.REVIEW && (
                        <div className="mt-6 p-4 bg-emerald-50 border border-emerald-100 rounded-lg animate-pulse flex items-center gap-3">
                           <ClipboardDocumentCheckIcon className="w-6 h-6 text-emerald-600" />
                           <span className="text-emerald-800 font-medium">บรรณาธิการกำลังตรวจทานผลงานของคุณ...</span>
                        </div>
                      )}
                   </div>
                </div>

                <div className="lg:col-span-1">
                   <AgentLog logs={logs} />
                </div>
              </div>
            )}

            {/* Final Result View */}
            {step === WorkflowStep.COMPLETED && (
               <BookPreview 
                  ebook={eBook as EBook} 
                  onRestart={() => {
                    setTopic('');
                    setStep(WorkflowStep.INPUT);
                    setEBook({ chapters: [] });
                    setLogs([]);
                    setCoverStyle('Minimalist');
                  }} 
               />
            )}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

export interface Chapter {
  id: string;
  title: string;
  content?: string;
  status: 'pending' | 'generating' | 'completed' | 'error';
}

export interface EBook {
  topic: string;
  title: string;
  targetAudience: string;
  description: string;
  chapters: Chapter[];
  coverImage?: string;
  coverStyle?: string;
  tone?: string;
  authorBio?: string;
}

export enum AgentRole {
  STRATEGIST = 'นักวางกลยุทธ์',
  WRITER = 'นักเขียน',
  DESIGNER = 'นักออกแบบ',
  REVIEWER = 'บรรณาธิการ'
}

export interface LogEntry {
  timestamp: Date;
  agent: AgentRole;
  message: string;
}

export enum WorkflowStep {
  INPUT = 0,
  OUTLINE = 1,
  APPROVAL = 2, // New step: Review Outline before writing
  WRITING = 3,
  DESIGN = 4,
  REVIEW = 5,
  COMPLETED = 6
}

import { GoogleGenAI, Type } from "@google/genai";
import { Chapter, EBook } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("ไม่พบ API Key กรุณาตั้งค่า process.env.API_KEY");
  }
  return new GoogleGenAI({ apiKey });
};

// 1. Agent: Senior Strategist (15+ Years Experience)
export const generateBookOutline = async (topic: string): Promise<Partial<EBook>> => {
  const ai = getClient();

  const prompt = `
    You are a World-Class E-Book Strategist and Editor-in-Chief with over 15 years of experience in the publishing industry.
    You have a track record of creating best-selling non-fiction books globally.
    Your expertise lies in crafting compelling, market-driven book structures that hook readers instantly and deliver immense value.

    Your task is to plan a high-quality non-fiction e-book based on the user's topic: "${topic}".

    1. Create a magnetic, professional Title in Thai language that sounds like a bestseller (Catchy, Clear, and Compelling).
    2. Define a specific, high-potential Target Audience in Thai language.
    3. Write a captivating, high-converting Description in Thai language that emphasizes the benefits to the reader.
    4. Create an outline with exactly 4 distinct chapters. Each chapter must flow logically to build a complete narrative or guide.

    The content MUST be in Thai Language and reflect the depth, structure, and strategic thinking of a seasoned expert.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          targetAudience: { type: Type.STRING },
          description: { type: Type.STRING },
          chapters: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                summary: { type: Type.STRING } // Helper for the writer later
              },
              required: ["title", "summary"]
            }
          }
        },
        required: ["title", "targetAudience", "description", "chapters"]
      }
    }
  });

  if (!response.text) throw new Error("ไม่สามารถสร้างโครงเรื่องได้");

  const data = JSON.parse(response.text);

  // Transform to our internal Chapter type
  const chapters: Chapter[] = data.chapters.map((c: any, index: number) => ({
    id: `ch-${index}`,
    title: c.title,
    content: '',
    status: 'pending'
  }));

  // Add a Conclusion chapter explicitly
  chapters.push({
    id: 'ch-conclusion',
    title: 'บทสรุป: บทเรียนสำคัญและข้อคิดส่งท้าย',
    content: '',
    status: 'pending'
  });

  return {
    title: data.title,
    targetAudience: data.targetAudience,
    description: data.description,
    chapters: chapters
  };
};

// 2. Agent: Senior Ghostwriter (15+ Years Experience)
export const generateChapterContent = async (
  bookTitle: string, 
  chapterTitle: string, 
  audience: string,
  bookDescription: string,
  tone: string = "Professional & Authoritative",
  authorBio: string = ""
): Promise<string> => {
  const ai = getClient();

  const prompt = `
    You are a Senior Professional Ghostwriter and Editor with over 15 years of experience.

    Task: Write a chapter for a non-fiction e-book.

    Context:
    - Book Title: ${bookTitle}
    - Book Description: ${bookDescription}
    - Target Audience: ${audience}
    - Chapter Title: ${chapterTitle}

    Style & Voice Configuration:
    - Language: Thai (Eloquent, Natural, High-quality).
    - Tone of Voice: ${tone}.
    - Author Persona: ${authorBio ? `Write from the perspective of this author: "${authorBio}". Incorporate their expertise/vibe if applicable.` : 'Expert in the field.'}

    Requirements:
    - Length: Approximately 500-700 words.
    - Structure: Use engaging headers, concise paragraphs, and bullet points for readability. Format in Markdown.
    - Quality: Provide deep insights, practical real-world examples (use case studies if relevant to the topic), and avoid generic "AI-sounding" fluff.
    - Engagement: Speak directly to the reader ("คุณ").

    If this is the Conclusion chapter (บทสรุป), synthesize the wisdom into a powerful call-to-action.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: prompt,
  });

  return response.text || "เกิดข้อผิดพลาดในการสร้างเนื้อหา";
};

// 3. Agent: Senior Art Director (15+ Years Experience)
export const generateCoverImage = async (title: string, description: string, style: string = 'Minimalist'): Promise<string> => {
  const ai = getClient();

  // First, generate a prompt for the image model based on the book info
  const promptDesignResponse = await ai.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: `You are a Senior Art Director with 15 years of experience in Book Cover Design.
    Create a highly detailed, artistic image generation prompt for a non-fiction e-book cover.

    Book Title: "${title}". 
    Description: "${description}".
    Target Aesthetic Style: "${style}".

    Style Guidelines:
    - Focus heavily on the "${style}" visual style.
    - Ensure the design looks professional, eye-catching, and like a global Best Seller.
    - Use typography and visual hierarchy effectively.
    - Avoid text glitches (the image generation model should not render complex text, just the visual art).

    Output only the English prompt text for the image generator.`
  });

  const imagePrompt = promptDesignResponse.text || `A professional book cover for ${title} in ${style} style`;

  // Generate the actual image
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview', // Using the advanced image model
      contents: {
        parts: [{ text: imagePrompt }]
      },
      config: {
        imageConfig: {
            aspectRatio: "3:4", // Standard book ratio
            imageSize: "1K"
        }
      }
    });

    // Extract image
    for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
            return `data:image/png;base64,${part.inlineData.data}`;
        }
    }

    throw new Error("ไม่ได้รับข้อมูลรูปภาพกลับมาจาก API");

  } catch (e) {
    console.error("Image gen error", e);
    return "https://picsum.photos/600/800"; // Fallback
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Chapter, EBook, AgentRole, LogEntry, WorkflowStep } from './types';
import { generateBookOutline, generateChapterContent, generateCoverImage } from './services/geminiService';
import { AgentLog } from './components/AgentLog';
import { BookPreview } from './components/BookPreview';
import { 
  BeakerIcon, 
  BookOpenIcon, 
  PencilIcon, 
  SparklesIcon, 
  ChevronRightIcon, 
  UserIcon,
  ArrowRightIcon,
  ClipboardDocumentCheckIcon,
  CheckCircleIcon,
  ArrowPathIcon
} from '@heroicons/react/24/solid';

const COVER_STYLES = ['Minimalist', 'Vibrant', 'Vintage', 'Modern', 'Abstract', 'Futuristic', 'Corporate', 'Luxury'];
const TONES = [
  { id: 'Professional', label: 'มืออาชีพและน่าเชื่อถือ (Professional)', desc: 'เหมาะสำหรับธุรกิจ การเงิน วิชาการ' },
  { id: 'Friendly', label: 'เป็นกันเองและเข้าถึงง่าย (Friendly)', desc: 'เหมาะสำหรับไลฟ์สไตล์ การพัฒนาตนเอง' },
  { id: 'Storytelling', label: 'เน้นการเล่าเรื่อง (Storytelling)', desc: 'เหมาะสำหรับประวัติ แรงบันดาลใจ' },
  { id: 'Persuasive', label: 'โน้มน้าวใจ (Persuasive)', desc: 'เหมาะสำหรับการขาย การตลาด' },
  { id: 'Humorous', label: 'สนุกสนานและมีอารมณ์ขัน (Humorous)', desc: 'เหมาะสำหรับเนื้อหาเบาสมอง' }
];

const App: React.FC = () => {
  // Input States
  const [topic, setTopic] = useState('');
  const [coverStyle, setCoverStyle] = useState<string>('Minimalist');
  const [tone, setTone] = useState<string>('Professional');
  const [authorBio, setAuthorBio] = useState('');

  // Workflow States
  const [step, setStep] = useState<WorkflowStep>(WorkflowStep.INPUT);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [eBook, setEBook] = useState<Partial<EBook>>({ chapters: [] });
  const [isProcessing, setIsProcessing] = useState(false);

  const addLog = (agent: AgentRole, message: string) => {
    setLogs(prev => [...prev, { timestamp: new Date(), agent, message }]);
  };

  const handleStartStrategy = async () => {
    if (!topic.trim()) return;
    setStep(WorkflowStep.OUTLINE);
    setIsProcessing(true);
    setLogs([]); 

    try {
      addLog(AgentRole.STRATEGIST, `เริ่มโปรเจกต์: "${topic}"`);
      addLog(AgentRole.STRATEGIST, "กำลังวิเคราะห์ตลาดและวางโครงเรื่อง...");

      const outlineData = await generateBookOutline(topic);

      // Save initial config
      setEBook({ 
        ...outlineData, 
        coverStyle, 
        tone, 
        authorBio 
      });

      addLog(AgentRole.STRATEGIST, `วางโครงเรื่องเสร็จสิ้น: ${outlineData.title}`);
      addLog(AgentRole.STRATEGIST, "รอการอนุมัติโครงเรื่องจากผู้ใช้งาน...");

      setIsProcessing(false);
      setStep(WorkflowStep.APPROVAL); // Pause for user approval

    } catch (error) {
      addLog(AgentRole.STRATEGIST, `เกิดข้อผิดพลาด: ${(error as Error).message}`);
      setIsProcessing(false);
      setStep(WorkflowStep.INPUT);
    }
  };

  const handleApproveOutline = () => {
    setStep(WorkflowStep.WRITING);
    setIsProcessing(true);
  };

  const handleRegenerateOutline = () => {
    handleStartStrategy();
  };

  // Effect to handle the Writing Phase
  useEffect(() => {
    const processWriting = async () => {
      if (step === WorkflowStep.WRITING && eBook.chapters && eBook.chapters.length > 0) {

        const newChapters = [...eBook.chapters];

        for (let i = 0; i < newChapters.length; i++) {
          const chapter = newChapters[i];
          if (chapter.status === 'pending') {

            newChapters[i].status = 'generating';
            setEBook(prev => ({ ...prev, chapters: [...newChapters] }));

            const isConclusion = chapter.id === 'ch-conclusion';
            addLog(AgentRole.WRITER, `${isConclusion ? 'บทสรุป' : `บทที่ ${i + 1}`}: กำลังเขียน...`);

            try {
              const content = await generateChapterContent(
                eBook.title || "หนังสือ", 
                chapter.title, 
                eBook.targetAudience || "ผู้อ่านทั่วไป",
                eBook.description || "",
                eBook.tone,
                eBook.authorBio
              );

              newChapters[i].content = content;
              newChapters[i].status = 'completed';
              setEBook(prev => ({ ...prev, chapters: [...newChapters] }));

              addLog(AgentRole.WRITER, `${isConclusion ? 'บทสรุป' : `บทที่ ${i + 1}`} เขียนเสร็จแล้ว`);

            } catch (err) {
              addLog(AgentRole.WRITER, `เกิดข้อผิดพลาดในบทที่ ${i + 1}`);
              newChapters[i].status = 'error';
              setEBook(prev => ({ ...prev, chapters: [...newChapters] }));
            }
          }
        }

        setStep(WorkflowStep.DESIGN);
      }
    };

    if (step === WorkflowStep.WRITING) {
      processWriting();
    }
  }, [step, eBook.chapters]);

  // Effect to handle Design Phase
  useEffect(() => {
    const processDesign = async () => {
      if (step === WorkflowStep.DESIGN) {
        addLog(AgentRole.DESIGNER, `เริ่มออกแบบปกสไตล์ ${eBook.coverStyle || coverStyle}...`);
        try {
          const imageUrl = await generateCoverImage(eBook.title || "", eBook.description || "", eBook.coverStyle || coverStyle);
          setEBook(prev => ({ ...prev, coverImage: imageUrl }));
          addLog(AgentRole.DESIGNER, "ออกแบบปกเสร็จสิ้น");

          setTimeout(() => {
             setStep(WorkflowStep.REVIEW);
          }, 1000);

        } catch (e) {
            addLog(AgentRole.DESIGNER, "ไม่สามารถสร้างภาพปกได้ ใช้ภาพสำรองแทน");
            setStep(WorkflowStep.REVIEW);
        }
      }
    };

    if (step === WorkflowStep.DESIGN) {
      processDesign();
    }
  }, [step, eBook.title]);

  // Effect to handle Review Phase
  useEffect(() => {
    const processReview = async () => {
        if (step === WorkflowStep.REVIEW) {
            addLog(AgentRole.REVIEWER, "QC: กำลังตรวจสอบคุณภาพเนื้อหาทั้งหมด...");

            // Artificial delay for UX
            await new Promise(r => setTimeout(r, 1500));
            addLog(AgentRole.REVIEWER, "QC: เนื้อหาครบถ้วนสมบูรณ์");

            await new Promise(r => setTimeout(r, 800));
            addLog(AgentRole.REVIEWER, "QC: การจัดรูปแบบพร้อมใช้งาน");

            addLog(AgentRole.REVIEWER, "เสร็จสิ้นทุกขั้นตอน พร้อมส่งมอบ");
            setTimeout(() => {
                setIsProcessing(false);
                setStep(WorkflowStep.COMPLETED);
            }, 800);
        }
    }

    if (step === WorkflowStep.REVIEW) {
        processReview();
    }
  }, [step]);


  const StepIcon = ({ current, target, icon: Icon, label }: { current: WorkflowStep, target: WorkflowStep, icon: any, label: string }) => {
    const isActive = current === target;
    const isCompleted = current > target;

    return (
      <div className={`flex flex-col items-center z-10 w-20 transition-all duration-300 ${isActive ? 'scale-110' : 'opacity-70'}`}>
        <div className={`w-10 h-10 lg:w-12 lg:h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500
          ${isCompleted ? 'bg-green-500 border-green-500 text-white' : 
            isActive ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg shadow-indigo-200' : 
            'bg-white border-slate-300 text-slate-300'}`}>
          <Icon className="w-5 h-5 lg:w-6 lg:h-6" />
        </div>
        <span className={`mt-2 text-[10px] lg:text-xs font-semibold text-center hidden sm:block ${isActive ? 'text-indigo-600' : isCompleted ? 'text-green-600' : 'text-slate-400'}`}>
           {label}
        </span>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans pb-20">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-indigo-600 text-white p-1.5 rounded-lg">
                <SparklesIcon className="w-5 h-5" />
            </div>
            <h1 className="text-lg sm:text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-purple-600">
              SoloPreneur E-Book Architect
            </h1>
          </div>
          <div className="text-xs sm:text-sm text-slate-500 hidden sm:block bg-slate-100 px-3 py-1 rounded-full">
            AI One-Stop Service v2.0
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Progress Stepper */}
        {step !== WorkflowStep.INPUT && (
          <div className="mb-10 relative max-w-4xl mx-auto">
            <div className="absolute top-5 lg:top-6 left-10 right-10 h-0.5 bg-slate-200 -z-0"></div>
            <div className="absolute top-5 lg:top-6 left-10 h-0.5 bg-indigo-500 transition-all duration-700 -z-0" 
                 style={{ width: `${Math.min(((step) / 6) * 100, 100)}%` }}></div>
            <div className="flex justify-between relative">
               <StepIcon current={step} target={WorkflowStep.OUTLINE} icon={BeakerIcon} label="วิเคราะห์" />
               <StepIcon current={step} target={WorkflowStep.APPROVAL} icon={CheckCircleIcon} label="อนุมัติโครง" />
               <StepIcon current={step} target={WorkflowStep.WRITING} icon={PencilIcon} label="เขียนเนื้อหา" />
               <StepIcon current={step} target={WorkflowStep.DESIGN} icon={SparklesIcon} label="ออกแบบ" />
               <StepIcon current={step} target={WorkflowStep.REVIEW} icon={ClipboardDocumentCheckIcon} label="ตรวจสอบ" />
               <StepIcon current={step} target={WorkflowStep.COMPLETED} icon={BookOpenIcon} label="เสร็จสิ้น" />
            </div>
          </div>
        )}

        {/* STEP 0: INPUT CONFIGURATION */}
        {step === WorkflowStep.INPUT && (
          <div className="max-w-3xl mx-auto mt-6 animate-fade-in">
            <div className="bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden">
              <div className="bg-indigo-600 p-8 text-center text-white">
                 <h2 className="text-3xl font-bold mb-2">สร้าง E-Book ระดับมืออาชีพ</h2>
                 <p className="text-indigo-100">ครบวงจรตั้งแต่ วางแผน เขียนเนื้อหา และออกแบบปก ในคลิกเดียว</p>
              </div>

              <div className="p-8 space-y-8">
                {/* Topic Input */}
                <div>
                    <label className="block text-slate-700 font-semibold mb-2 text-lg">
                        1. คุณอยากเขียนเรื่องอะไร? <span className="text-red-500">*</span>
                    </label>
                    <input
                      type="text"
                      value={topic}
                      onChange={(e) => setTopic(e.target.value)}
                      placeholder="เช่น คู่มือการลงทุนอสังหาฯ ฉบับมนุษย์เงินเดือน, จิตวิทยาการขายออนไลน์..."
                      className="w-full px-5 py-4 text-lg border-2 border-slate-200 rounded-xl focus:border-indigo-500 focus:ring-4 focus:ring-indigo-50 outline-none transition-all"
                    />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {/* Tone Selection */}
                    <div>
                        <label className="block text-slate-700 font-semibold mb-3">
                            2. น้ำเสียงในการเขียน (Tone)
                        </label>
                        <div className="space-y-2">
                            {TONES.map((t) => (
                                <div 
                                    key={t.id}
                                    onClick={() => setTone(t.id)}
                                    className={`p-3 rounded-lg border-2 cursor-pointer transition-all flex items-center gap-3 ${
                                        tone === t.id 
                                        ? 'border-indigo-500 bg-indigo-50' 
                                        : 'border-slate-100 hover:border-indigo-200'
                                    }`}
                                >
                                    <div className={`w-4 h-4 rounded-full border-2 flex items-center justify-center ${tone === t.id ? 'border-indigo-600' : 'border-slate-300'}`}>
                                        {tone === t.id && <div className="w-2 h-2 rounded-full bg-indigo-600" />}
                                    </div>
                                    <div>
                                        <div className={`font-medium text-sm ${tone === t.id ? 'text-indigo-900' : 'text-slate-700'}`}>{t.label}</div>
                                        <div className="text-xs text-slate-400">{t.desc}</div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Style & Author */}
                    <div className="space-y-6">
                        {/* Cover Style */}
                        <div>
                            <label className="block text-slate-700 font-semibold mb-3">
                                3. สไตล์ภาพปก (Design Style)
                            </label>
                            <div className="flex flex-wrap gap-2">
                                {COVER_STYLES.map((style) => (
                                    <button
                                    key={style}
                                    onClick={() => setCoverStyle(style)}
                                    className={`px-3 py-1.5 rounded-full text-xs font-medium transition-all border ${
                                        coverStyle === style
                                        ? 'bg-indigo-600 text-white border-indigo-600 shadow-md shadow-indigo-200'
                                        : 'bg-white border-slate-200 text-slate-600 hover:border-indigo-300 hover:text-indigo-600'
                                    }`}
                                    >
                                    {style}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Author Bio */}
                        <div>
                             <label className="block text-slate-700 font-semibold mb-2">
                                4. ข้อมูลผู้เขียน (Optional)
                            </label>
                            <textarea 
                                value={authorBio}
                                onChange={(e) => setAuthorBio(e.target.value)}
                                placeholder="เช่น ผู้เชี่ยวชาญด้านการตลาด 10 ปี, เจ้าของเพจ..., ชอบเล่าเรื่องตลก"
                                className="w-full px-4 py-3 text-sm border-2 border-slate-200 rounded-xl focus:border-indigo-500 outline-none h-32 resize-none"
                            ></textarea>
                            <p className="text-xs text-slate-400 mt-1">*ช่วยให้ AI เขียนได้เหมือนคุณมากขึ้น</p>
                        </div>
                    </div>
                </div>

                <div className="pt-6 border-t border-slate-100 flex justify-end">
                    <button
                        onClick={handleStartStrategy}
                        disabled={!topic.trim() || isProcessing}
                        className="bg-indigo-600 text-white px-8 py-4 rounded-xl font-bold text-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-lg shadow-indigo-200 flex items-center gap-2 transform hover:translate-y-[-2px]"
                    >
                        {isProcessing ? 'กำลังประมวลผล...' : 'เริ่มสร้าง E-Book'} <ChevronRightIcon className="w-5 h-5" />
                    </button>
                </div>

              </div>
            </div>
          </div>
        )}

        {/* STEP 2: APPROVAL SCREEN */}
        {step === WorkflowStep.APPROVAL && (
            <div className="max-w-5xl mx-auto mt-6 animate-fade-in">
                <div className="flex flex-col md:flex-row gap-6">
                    {/* Outline Preview */}
                    <div className="flex-1 bg-white p-8 rounded-2xl shadow-xl border border-slate-200">
                        <div className="flex justify-between items-start mb-6">
                            <h2 className="text-2xl font-bold text-slate-800">ยืนยันโครงเรื่อง (Blueprint)</h2>
                            <span className="bg-yellow-100 text-yellow-800 text-xs px-3 py-1 rounded-full font-medium">รอการอนุมัติ</span>
                        </div>

                        <div className="space-y-6">
                            <div className="p-4 bg-slate-50 rounded-xl border border-slate-100">
                                <label className="text-xs font-bold text-slate-400 uppercase">ชื่อเรื่อง</label>
                                <h3 className="text-xl font-bold text-indigo-900 mt-1">{eBook.title}</h3>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase">กลุ่มเป้าหมาย</label>
                                    <p className="text-slate-700 text-sm mt-1">{eBook.targetAudience}</p>
                                </div>
                                <div>
                                    <label className="text-xs font-bold text-slate-400 uppercase">สไตล์การเขียน</label>
                                    <p className="text-slate-700 text-sm mt-1">{TONES.find(t => t.id === eBook.tone)?.label || eBook.tone}</p>
                                </div>
                            </div>

                            <div>
                                <label className="text-xs font-bold text-slate-400 uppercase mb-2 block">สารบัญ</label>
                                <div className="space-y-2">
                                    {eBook.chapters?.map((chap, idx) => (
                                        <div key={idx} className="flex items-center gap-3 p-3 bg-white border border-slate-200 rounded-lg shadow-sm">
                                            <div className="w-8 h-8 rounded-full bg-slate-100 text-slate-500 flex items-center justify-center font-bold text-sm shrink-0">
                                                {chap.id === 'ch-conclusion' ? 'End' : idx + 1}
                                            </div>
                                            <span className="text-slate-700 font-medium">{chap.title}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>

                        <div className="mt-8 flex gap-4">
                            <button 
                                onClick={handleRegenerateOutline}
                                className="flex-1 py-3 px-4 bg-white border-2 border-slate-200 text-slate-600 rounded-xl font-semibold hover:border-slate-400 hover:text-slate-800 transition-all flex justify-center items-center gap-2"
                            >
                                <ArrowPathIcon className="w-5 h-5" /> สร้างโครงเรื่องใหม่
                            </button>
                            <button 
                                onClick={handleApproveOutline}
                                className="flex-[2] py-3 px-4 bg-indigo-600 text-white rounded-xl font-bold text-lg hover:bg-indigo-700 shadow-lg shadow-indigo-200 transition-all flex justify-center items-center gap-2"
                            >
                                <CheckCircleIcon className="w-6 h-6" /> อนุมัติ & เริ่มเขียนทันที
                            </button>
                        </div>
                    </div>

                    {/* Sidebar Log */}
                    <div className="w-full md:w-80">
                         <AgentLog logs={logs} />
                    </div>
                </div>
            </div>
        )}

        {/* PROCESSING & COMPLETED VIEWS */}
        {(step > WorkflowStep.APPROVAL) && (
          <div className="grid grid-cols-1 gap-6">

            {/* Live Status Area */}
            {step !== WorkflowStep.COMPLETED && (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-fade-in">
                <div className="lg:col-span-2">
                   <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 min-h-[300px]">
                      <h3 className="font-bold text-lg mb-4 flex items-center gap-2">
                        สถานะการทำงาน (Work In Progress)
                      </h3>

                      <div className="mb-6 flex gap-4 p-4 bg-slate-50 rounded-lg border border-slate-100">
                            <div className="w-16 h-20 bg-slate-200 rounded shadow-sm shrink-0 overflow-hidden">
                                {eBook.coverImage ? (
                                    <img src={eBook.coverImage} className="w-full h-full object-cover" />
                                ) : (
                                    <div className="w-full h-full flex items-center justify-center text-slate-300 text-xs text-center p-1">No Cover</div>
                                )}
                            </div>
                            <div>
                                <div className="text-lg font-bold text-slate-800 line-clamp-1">{eBook.title}</div>
                                <div className="text-slate-500 text-sm line-clamp-2">{eBook.description}</div>
                                <div className="flex gap-2 mt-2">
                                    <span className="text-[10px] bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full">{eBook.tone}</span>
                                    <span className="text-[10px] bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full">{eBook.coverStyle}</span>
                                </div>
                            </div>
                      </div>

                      {/* Chapter Progress Grid */}
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                        {eBook.chapters?.map((chap, idx) => (
                            <div key={idx} className={`p-3 rounded-lg border flex items-center justify-between transition-all duration-300 ${
                            chap.status === 'completed' ? 'bg-green-50 border-green-200 shadow-sm' :
                            chap.status === 'generating' ? 'bg-indigo-50 border-indigo-200 ring-1 ring-indigo-200 shadow-md scale-[1.02]' :
                            'bg-white border-slate-100 opacity-60'
                            }`}>
                            <div className="flex items-center gap-3 overflow-hidden">
                                <div className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold ${
                                    chap.status === 'completed' ? 'bg-green-200 text-green-700' : 
                                    chap.status === 'generating' ? 'bg-indigo-200 text-indigo-700' : 'bg-slate-200 text-slate-500'
                                }`}>
                                    {chap.status === 'completed' ? <CheckCircleIcon className="w-4 h-4" /> : (idx + 1)}
                                </div>
                                <span className="text-sm font-medium truncate text-slate-700">
                                    {chap.title}
                                </span>
                            </div>
                            {chap.status === 'generating' && <div className="w-2 h-2 rounded-full bg-indigo-500 animate-ping"></div>}
                            </div>
                        ))}
                      </div>
                   </div>
                </div>

                <div className="lg:col-span-1">
                   <AgentLog logs={logs} />
                </div>
              </div>
            )}

            {/* Final Result View */}
            {step === WorkflowStep.COMPLETED && (
               <BookPreview 
                  ebook={eBook as EBook} 
                  onRestart={() => {
                    setTopic('');
                    setStep(WorkflowStep.INPUT);
                    setEBook({ chapters: [] });
                    setLogs([]);
                  }} 
               />
            )}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

