  { id: 'Academic', label: 'วิชาการและเชิงลึก (Academic)', desc: 'เหมาะสำหรับตำรา งานวิจัย หรือคู่มือเฉพาะทาง' },
  { id: 'Inspirational', label: 'สร้างแรงบันดาลใจ (Inspirational)', desc: 'เหมาะสำหรับหนังสือพัฒนาตนเอง ปลุกไฟ' },
  { id: 'Direct', label: 'กระชับ เน้นการลงมือทำ (Direct)', desc: 'เหมาะสำหรับ How-to และคู่มือปฏิบัติ' },
  { id: 'Empathetic', label: 'อ่อนโยนและเข้าอกเข้าใจ (Empathetic)', desc: 'เหมาะสำหรับจิตวิทยา สุขภาพ ความสัมพันธ์' },
  { id: 'Witty', label: 'หลักแหลมและทันสมัย (Witty)', desc: 'เหมาะสำหรับบทวิเคราะห์สังคม เทรนด์ใหม่ๆ' },
  { id: 'Casual', label: 'เพื่อนเล่าให้เพื่อนฟัง (Casual)', desc: 'ภาษาง่ายๆ เป็นกันเอง เหมือนนั่งคุยกันในวงสนทนา' },
  { id: 'GenZ', label: 'วัยรุ่น Gen Z (Trendy)', desc: 'ใช้สแลง คำศัพท์สมัยใหม่ สนุกสนาน เข้าถึงวัยรุ่น' }
];

const App: React.FC = () => {
  // Input States
  const [topic, setTopic] = useState('');
  const [coverStyle, setCoverStyle] = useState<string>('Minimalist');
  const [tone, setTone] = useState<string>('Professional');
  const [authorBio, setAuthorBio] = useState('');

  // Workflow States
  const [step, setStep] = useState<WorkflowStep>(WorkflowStep.INPUT);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [eBook, setEBook] = useState<Partial<EBook>>({ chapters: [] });
  const [isProcessing, setIsProcessing] = useState(false);

  const addLog = (agent: AgentRole, message: string) => {
    setLogs(prev => [...prev, { timestamp: new Date(), agent, message }]);
  };

  const handleStartStrategy = async () => {
    if (!topic.trim()) return;
    setStep(WorkflowStep.OUTLINE);
    setIsProcessing(true);
    setLogs([]); 

    try {
      addLog(AgentRole.STRATEGIST, `เริ่มโปรเจกต์: "${topic}"`);
      addLog(AgentRole.STRATEGIST, "กำลังวิเคราะห์ตลาดและวางโครงเรื่อง...");

      const outlineData = await generateBookOutline(topic);

      // Save initial config
      setEBook({ 
        ...outlineData, 
        coverStyle, 
        tone, 
        authorBio 
      });

      addLog(AgentRole.STRATEGIST, `วางโครงเรื่องเสร็จสิ้น: ${outlineData.title}`);
      addLog(AgentRole.STRATEGIST, "รอการอนุมัติโครงเรื่องจากผู้ใช้งาน...");

      setIsProcessing(false);
      setStep(WorkflowStep.APPROVAL); // Pause for user approval

    } catch (error) {
      addLog(AgentRole.STRATEGIST, `เกิดข้อผิดพลาด: ${(error as Error).message}`);
      setIsProcessing(false);
      setStep(WorkflowStep.INPUT);
    }
  };

  const handleApproveOutline = () => {
    setStep(WorkflowStep.WRITING);
    setIsProcessing(true);
  };

  const handleRegenerateOutline = () => {
    handleStartStrategy();
  };

  const handleUpdateChapter = (index: number, newContent: string) => {
    setEBook(prev => {
      if (!prev.chapters) return prev;
      const updatedChapters = [...prev.chapters];
      updatedChapters[index] = {
        ...updatedChapters[index],
        content: newContent
      };
      return { ...prev, chapters: updatedChapters };
    });
  };

  // Effect to handle the Writing Phase
  useEffect(() => {
    const processWriting = async () => {
      if (step === WorkflowStep.WRITING && eBook.chapters && eBook.chapters.length > 0) {

        const newChapters = [...eBook.chapters];

        for (let i = 0; i < newChapters.length; i++) {
          const chapter = newChapters[i];
          if (chapter.status === 'pending') {

            newChapters[i].status = 'generating';
            setEBook(prev => ({ ...prev, chapters: [...newChapters] }));

            const isConclusion = chapter.id === 'ch-conclusion';
            addLog(AgentRole.WRITER, `${isConclusion ? 'บทสรุป' : `บทที่ ${i + 1}`}: กำลังเขียน...`);

            try {
              const content = await generateChapterContent(
                eBook.title || "หนังสือ", 
                chapter.title, 
                eBook.targetAudience || "ผู้อ่านทั่วไป",
                eBook.description || "",
                eBook.tone,
                eBook.authorBio
              );

              newChapters[i].content = content;
              newChapters[i].status = 'completed';
              setEBook(prev => ({ ...prev, chapters: [...newChapters] }));

              addLog(AgentRole.WRITER, `${isConclusion ? 'บทสรุป' : `บทที่ ${i + 1}`} เขียนเสร็จแล้ว`);

            } catch (err) {
              addLog(AgentRole.WRITER, `เกิดข้อผิดพลาดในบทที่ ${i + 1}`);
              newChapters[i].status = 'error';
              setEBook(prev => ({ ...prev, chapters: [...newChapters] }));
            }
          }
        }

        setStep(WorkflowStep.DESIGN);
      }
    };

    if (step === WorkflowStep.WRITING) {
      processWriting();
    }
  }, [step, eBook.chapters]);

  // Effect to handle Design Phase
  useEffect(() => {
    const processDesign = async () => {
      if (step === WorkflowStep.DESIGN) {
        addLog(AgentRole.DESIGNER, `เริ่มออกแบบปกสไตล์ ${eBook.coverStyle || coverStyle}...`);
        try {
          const imageUrl = await generateCoverImage(eBook.title || "", eBook.description || "", eBook.coverStyle || coverStyle);
          setEBook(prev => ({ ...prev, coverImage: imageUrl }));
          addLog(AgentRole.DESIGNER, "ออกแบบปกเสร็จสิ้น");

          setTimeout(() => {
             setStep(WorkflowStep.REVIEW);
          }, 1000);

        } catch (e) {
            addLog(AgentRole.DESIGNER, "ไม่สามารถสร้างภาพปกได้ ใช้ภาพสำรองแทน");
            setStep(WorkflowStep.REVIEW);
        }
      }
    };

    if (step === WorkflowStep.DESIGN) {
      processDesign();
    }
  }, [step, eBook.title]);

  // Effect to handle Review Phase
  useEffect(() => {
    const processReview = async () => {
        if (step === WorkflowStep.REVIEW) {
            addLog(AgentRole.REVIEWER, "QC: กำลังตรวจสอบคุณภาพเนื้อหาทั้งหมด...");

            // Artificial delay for UX
            await new Promise(r => setTimeout(r, 1500));
            addLog(AgentRole.REVIEWER, "QC: เนื้อหาครบถ้วนสมบูรณ์");

            await new Promise(r => setTimeout(r, 800));
            addLog(AgentRole.REVIEWER, "QC: การจัดรูปแบบพร้อมใช้งาน");

            addLog(AgentRole.REVIEWER, "เสร็จสิ้นทุกขั้นตอน พร้อมส่งมอบ");
            setTimeout(() => {
                setIsProcessing(false);
                setStep(WorkflowStep.COMPLETED);
            }, 800);
        }
    }

    if (step === WorkflowStep.REVIEW) {
        processReview();
    }
  }, [step]);


  const StepIcon = ({ current, target, icon: Icon, label }: { current: WorkflowStep, target: WorkflowStep, icon: any, label: string }) => {
    const isActive = current === target;
    const isCompleted = current > target;

    return (
      <div className={`flex flex-col items-center z-10 w-20 transition-all duration-300 ${isActive ? 'scale-110' : 'opacity-70'}`}>
        <div className={`relative w-10 h-10 lg:w-12 lg:h-12 rounded-2xl flex items-center justify-center border-2 transition-all duration-500 shadow-md
          ${isCompleted ? 'bg-emerald-500 border-emerald-500 text-white' : 
            isActive ? 'bg-amber-600 border-amber-600 text-white shadow-lg shadow-amber-200' : 
            'bg-white border-stone-200 text-stone-300'}`}>

          {/* Active Animations: Pulse Ring & Spin Border */}
          {isActive && (
            <>
                <span className="absolute inline-flex h-full w-full rounded-2xl bg-amber-400 opacity-20 animate-ping"></span>
            </>
          )}

          <Icon className={`w-5 h-5 lg:w-6 lg:h-6 relative z-10 ${isActive ? 'animate-pulse' : ''}`} />
        </div>
        <span className={`mt-2 text-[10px] lg:text-xs font-semibold text-center hidden sm:block ${isActive ? 'text-amber-700' : isCompleted ? 'text-emerald-600' : 'text-stone-400'}`}>
           {label}
        </span>
      </div>
    );
  };

  return (
    <div className="min-h-screen pb-20 relative">
      {/* Header */}
      <header className="bg-white/80 backdrop-blur-md border-b border-stone-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-amber-600 text-white p-1.5 rounded-lg shadow-md shadow-amber-100">
                <SparklesIcon className="w-5 h-5" />
            </div>
            <h1 className="text-lg sm:text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-amber-700 to-orange-600">
              SoloPreneur E-Book Architect
            </h1>
          </div>
          <div className="text-xs sm:text-sm text-stone-500 hidden sm:block bg-stone-100/80 px-4 py-1.5 rounded-full border border-stone-200">
            AI One-Stop Service v2.0
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 relative z-20">

        {/* Progress Stepper */}
        {step !== WorkflowStep.INPUT && (
          <div className="mb-10 relative max-w-4xl mx-auto">
            <div className="absolute top-5 lg:top-6 left-10 right-10 h-0.5 bg-stone-200 -z-0"></div>
            <div className="absolute top-5 lg:top-6 left-10 h-0.5 bg-amber-500 transition-all duration-700 -z-0" 
                 style={{ width: `${Math.min(((step) / 6) * 100, 100)}%` }}></div>
            <div className="flex justify-between relative">
               <StepIcon current={step} target={WorkflowStep.OUTLINE} icon={BeakerIcon} label="วิเคราะห์" />
               <StepIcon current={step} target={WorkflowStep.APPROVAL} icon={CheckCircleIcon} label="อนุมัติโครง" />
               <StepIcon current={step} target={WorkflowStep.WRITING} icon={PencilIcon} label="เขียนเนื้อหา" />
               <StepIcon current={step} target={WorkflowStep.DESIGN} icon={SparklesIcon} label="ออกแบบ" />
               <StepIcon current={step} target={WorkflowStep.REVIEW} icon={ClipboardDocumentCheckIcon} label="ตรวจสอบ" />
               <StepIcon current={step} target={WorkflowStep.COMPLETED} icon={BookOpenIcon} label="เสร็จสิ้น" />
            </div>
          </div>
        )}

        {/* STEP 0: INPUT CONFIGURATION */}
        {step === WorkflowStep.INPUT && (
          <div className="max-w-3xl mx-auto mt-6 animate-fade-in">
            <div className="bg-white/90 backdrop-blur-sm rounded-3xl shadow-xl shadow-stone-200/50 border border-stone-100 overflow-hidden">
              <div className="bg-gradient-to-r from-amber-700 to-orange-600 p-10 text-center text-white relative overflow-hidden">
                 <div className="absolute top-0 left-0 w-full h-full bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
                 <h2 className="text-3xl font-bold mb-3 relative z-10 font-promt">สร้าง E-Book ระดับมืออาชีพ</h2>
                 <p className="text-amber-100 relative z-10 font-sarabun text-lg">ครบวงจรตั้งแต่ วางแผน เขียนเนื้อหา และออกแบบปก ในคลิกเดียว</p>
              </div>

              <div className="p-10 space-y-10">
                {/* Topic Input */}
                <div>
                    <label className="block text-stone-700 font-bold mb-3 text-lg">
                        1. คุณอยากเขียนเรื่องอะไร? <span className="text-red-400">*</span>
                    </label>
                    <input
                      type="text"
                      value={topic}
                      onChange={(e) => setTopic(e.target.value)}
                      placeholder="เช่น คู่มือการลงทุนอสังหาฯ ฉบับมนุษย์เงินเดือน, จิตวิทยาการขายออนไลน์..."
                      className="w-full px-5 py-4 text-lg border-2 border-stone-200 bg-stone-50 rounded-2xl focus:border-amber-500 focus:bg-white focus:ring-4 focus:ring-amber-50 outline-none transition-all placeholder-stone-400"
                    />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {/* Tone Selection */}
                    <div>
                        <label className="block text-stone-700 font-bold mb-4">
                            2. น้ำเสียงในการเขียน (Tone)
                        </label>
                        <div className="space-y-3">
                            {TONES.map((t) => (
                                <div 
                                    key={t.id}
                                    onClick={() => setTone(t.id)}
                                    className={`p-3 rounded-xl border-2 cursor-pointer transition-all flex items-center gap-3 group ${
                                        tone === t.id 
                                        ? 'border-amber-500 bg-amber-50' 
                                        : 'border-stone-100 hover:border-amber-200 bg-white'
                                    }`}
                                >
                                    <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center transition-colors ${tone === t.id ? 'border-amber-600' : 'border-stone-300 group-hover:border-amber-300'}`}>
                                        {tone === t.id && <div className="w-2.5 h-2.5 rounded-full bg-amber-600" />}
                                    </div>
                                    <div>
                                        <div className={`font-semibold text-sm ${tone === t.id ? 'text-amber-900' : 'text-stone-700'}`}>{t.label}</div>
                                        <div className="text-xs text-stone-400">{t.desc}</div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Style & Author */}
                    <div className="space-y-8">
                        {/* Cover Style */}
                        <div>
                            <label className="block text-stone-700 font-bold mb-4">
                                3. สไตล์ภาพปก (Design Style)
                            </label>
                            <div className="grid grid-cols-2 gap-2.5">
                                {COVER_STYLES.map((style) => (
                                    <button
                                    key={style.id}
                                    onClick={() => setCoverStyle(style.id)}
                                    className={`px-3 py-2.5 rounded-xl text-left transition-all border flex flex-col ${
                                        coverStyle === style.id
                                        ? 'bg-stone-800 text-white border-stone-800 shadow-lg shadow-stone-300'
                                        : 'bg-white border-stone-200 text-stone-600 hover:border-amber-400 hover:text-amber-700'
                                    }`}
                                    >
                                        <span className="font-bold text-sm">{style.label}</span>
                                        <span className={`text-[10px] ${coverStyle === style.id ? 'text-stone-300' : 'text-stone-400'}`}>
                                            {style.desc}
                                        </span>
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Author Bio */}
                        <div>
                             <label className="block text-stone-700 font-bold mb-3">
                                4. ข้อมูลผู้เขียน (Optional)
                            </label>
                            <textarea 
                                value={authorBio}
                                onChange={(e) => setAuthorBio(e.target.value)}
                                placeholder="เช่น ผู้เชี่ยวชาญด้านการตลาด 10 ปี, เจ้าของเพจ..., ชอบเล่าเรื่องตลก"
                                className="w-full px-4 py-3 text-sm border-2 border-stone-200 bg-stone-50 rounded-2xl focus:border-amber-500 focus:bg-white outline-none h-32 resize-none placeholder-stone-400"
                            ></textarea>
                            <p className="text-xs text-stone-400 mt-2 flex items-center gap-1">
                                <SparklesIcon className="w-3 h-3 text-amber-500" /> ช่วยให้ AI เขียนได้เหมือนคุณมากขึ้น
                            </p>
                        </div>
                    </div>
                </div>

                <div className="pt-8 border-t border-stone-100 flex justify-end">
                    <button
                        onClick={handleStartStrategy}
                        disabled={!topic.trim() || isProcessing}
                        className="bg-stone-800 text-white px-10 py-4 rounded-2xl font-bold text-lg hover:bg-stone-900 hover:scale-105 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 transition-all shadow-xl shadow-stone-300 flex items-center gap-3"
                    >
                        {isProcessing ? 'กำลังประมวลผล...' : 'เริ่มสร้าง E-Book'} <ArrowRightIcon className="w-5 h-5" />
                    </button>
                </div>

              </div>
            </div>
          </div>
        )}

        {/* STEP 2: APPROVAL SCREEN */}
        {step === WorkflowStep.APPROVAL && (
            <div className="max-w-5xl mx-auto mt-6 animate-fade-in">
                <div className="flex flex-col md:flex-row gap-6">
                    {/* Outline Preview */}
                    <div className="flex-1 bg-white/90 backdrop-blur-sm p-8 rounded-3xl shadow-xl border border-stone-200">
                        <div className="flex justify-between items-start mb-6">
                            <h2 className="text-2xl font-bold text-stone-800">ยืนยันโครงเรื่อง (Blueprint)</h2>
                            <span className="bg-amber-100 text-amber-800 text-xs px-3 py-1 rounded-full font-medium border border-amber-200">รอการอนุมัติ</span>
                        </div>

                        <div className="space-y-6">
                            <div className="p-6 bg-stone-50 rounded-2xl border border-stone-100">
                                <label className="text-xs font-bold text-stone-400 uppercase tracking-wider">ชื่อเรื่อง</label>
                                <h3 className="text-2xl font-bold text-stone-800 mt-2 font-promt leading-relaxed">{eBook.title}</h3>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div className="p-4 bg-white rounded-xl border border-stone-100 shadow-sm">
                                    <label className="text-xs font-bold text-stone-400 uppercase tracking-wider">กลุ่มเป้าหมาย</label>
                                    <p className="text-stone-700 text-sm mt-2">{eBook.targetAudience}</p>
                                </div>
                                <div className="p-4 bg-white rounded-xl border border-stone-100 shadow-sm">
                                    <label className="text-xs font-bold text-stone-400 uppercase tracking-wider">สไตล์การเขียน</label>
                                    <p className="text-stone-700 text-sm mt-2">{TONES.find(t => t.id === eBook.tone)?.label || eBook.tone}</p>
                                </div>
                            </div>

                            <div>
                                <label className="text-xs font-bold text-stone-400 uppercase mb-3 block tracking-wider">สารบัญ</label>
                                <div className="space-y-3">
                                    {eBook.chapters?.map((chap, idx) => (
                                        <div key={idx} className="flex items-center gap-4 p-4 bg-white border border-stone-100 rounded-xl shadow-sm hover:shadow-md transition-shadow">
                                            <div className="w-10 h-10 rounded-full bg-stone-100 text-stone-500 flex items-center justify-center font-bold text-sm shrink-0 border border-stone-200">
                                                {chap.id === 'ch-conclusion' ? 'End' : idx + 1}
                                            </div>
                                            <span className="text-stone-700 font-medium text-lg">{chap.title}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>

                        <div className="mt-10 flex gap-4">
                            <button 
                                onClick={handleRegenerateOutline}
                                className="flex-1 py-3 px-4 bg-white border-2 border-stone-200 text-stone-600 rounded-xl font-semibold hover:border-stone-400 hover:text-stone-800 transition-all flex justify-center items-center gap-2"
                            >
                                <ArrowPathIcon className="w-5 h-5" /> สร้างโครงเรื่องใหม่
                            </button>
                            <button 
                                onClick={handleApproveOutline}
                                className="flex-[2] py-4 px-6 bg-amber-600 text-white rounded-xl font-bold text-lg hover:bg-amber-700 shadow-lg shadow-amber-200 transition-all flex justify-center items-center gap-2 transform hover:translate-y-[-2px]"
                            >
                                <CheckCircleIcon className="w-6 h-6" /> อนุมัติ & เริ่มเขียนทันที
                            </button>
                        </div>
                    </div>

                    {/* Sidebar Log */}
                    <div className="w-full md:w-80">
                         <AgentLog logs={logs} />
                    </div>
                </div>
            </div>
        )}

        {/* PROCESSING & COMPLETED VIEWS */}
        {(step > WorkflowStep.APPROVAL) && (
          <div className="grid grid-cols-1 gap-6">

            {/* Live Status Area */}
            {step !== WorkflowStep.COMPLETED && (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-fade-in">
                <div className="lg:col-span-2">
                   <div className="bg-white/90 backdrop-blur-sm rounded-3xl shadow-sm border border-stone-200 p-8 min-h-[300px]">
                      <h3 className="font-bold text-xl mb-6 flex items-center gap-3 text-stone-800">
                        <span className="w-2 h-8 bg-amber-500 rounded-full inline-block"></span>
                        สถานะการทำงาน (Work In Progress)
                      </h3>

                      <div className="mb-8 flex gap-6 p-6 bg-stone-50 rounded-2xl border border-stone-100">
                            <div className="w-24 h-32 bg-stone-200 rounded-lg shadow-inner shrink-0 overflow-hidden relative group">
                                {eBook.coverImage ? (
                                    <img src={eBook.coverImage} className="w-full h-full object-cover shadow-sm" />
                                ) : (
                                    <div className="w-full h-full flex flex-col items-center justify-center text-stone-400 text-xs text-center p-2">
                                        <SparklesIcon className="w-6 h-6 mb-1 opacity-50" />
                                        Generating...
                                    </div>
                                )}
                            </div>
                            <div className="flex-1 min-w-0">
                                <div className="text-xl font-bold text-stone-800 line-clamp-1 font-promt">{eBook.title}</div>
                                <div className="text-stone-500 text-sm line-clamp-2 mt-1 leading-relaxed">{eBook.description}</div>
                                <div className="flex gap-2 mt-4">
                                    <span className="text-[10px] bg-amber-100 text-amber-800 px-3 py-1 rounded-full font-medium">{eBook.tone}</span>
                                    <span className="text-[10px] bg-stone-200 text-stone-600 px-3 py-1 rounded-full font-medium">{eBook.coverStyle}</span>
                                </div>
                            </div>
                      </div>

                      {/* Chapter Progress Grid */}
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        {eBook.chapters?.map((chap, idx) => (
                            <div key={idx} className={`p-4 rounded-xl border flex items-center justify-between transition-all duration-300 ${
                            chap.status === 'completed' ? 'bg-emerald-50 border-emerald-100 shadow-sm' :
                            chap.status === 'generating' ? 'bg-amber-50 border-amber-200 ring-1 ring-amber-200 shadow-md scale-[1.02]' :
                            'bg-white border-stone-100 opacity-60'
                            }`}>
                            <div className="flex items-center gap-3 overflow-hidden">
                                <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold transition-colors ${
                                    chap.status === 'completed' ? 'bg-emerald-200 text-emerald-700' : 
                                    chap.status === 'generating' ? 'bg-amber-200 text-amber-700' : 'bg-stone-200 text-stone-500'
                                }`}>
                                    {chap.status === 'completed' ? <CheckCircleIcon className="w-5 h-5" /> : (idx + 1)}
                                </div>
                                <span className="text-sm font-medium truncate text-stone-700">
                                    {chap.title}
                                </span>
                            </div>
                            {chap.status === 'generating' && <div className="w-2 h-2 rounded-full bg-amber-500 animate-ping"></div>}
                            </div>
                        ))}
                      </div>
                   </div>
                </div>

                <div className="lg:col-span-1">
                   <AgentLog logs={logs} />
                </div>
              </div>
            )}

            {/* Final Result View */}
            {step === WorkflowStep.COMPLETED && (
               <BookPreview 
                  ebook={eBook as EBook} 
                  onRestart={() => {
                    setTopic('');
                    setStep(WorkflowStep.INPUT);
                    setEBook({ chapters: [] });
                    setLogs([]);
                  }}
                  onUpdateChapter={handleUpdateChapter}
               />
            )}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useEffect, useRef } from 'react';
import { LogEntry, AgentRole } from '../types';

interface AgentLogProps {
  logs: LogEntry[];
}

const getAgentColor = (role: AgentRole) => {
  switch (role) {
    case AgentRole.STRATEGIST: return 'text-purple-700 bg-purple-100 border border-purple-200';
    case AgentRole.WRITER: return 'text-blue-700 bg-blue-100 border border-blue-200';
    case AgentRole.DESIGNER: return 'text-pink-700 bg-pink-100 border border-pink-200';
    case AgentRole.REVIEWER: return 'text-emerald-700 bg-emerald-100 border border-emerald-200';
    default: return 'text-stone-600 bg-stone-100 border border-stone-200';
  }
};

export const AgentLog: React.FC<AgentLogProps> = ({ logs }) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [logs]);

  return (
    <div className="bg-white/90 backdrop-blur-sm rounded-3xl shadow-lg border border-stone-200 h-96 flex flex-col overflow-hidden">
      <div className="p-4 bg-stone-50/80 border-b border-stone-100 font-bold text-stone-700 flex justify-between items-center">
        <span>บันทึกการทำงาน AI</span>
        <span className="flex items-center gap-1.5 text-xs font-normal text-stone-500 bg-white px-2 py-1 rounded-full border border-stone-200">
           <span className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></span>
           Live
        </span>
      </div>
      <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
        {logs.length === 0 && (
          <div className="flex flex-col items-center justify-center h-full text-stone-400 space-y-2 opacity-60">
             <div className="w-12 h-12 rounded-full bg-stone-100 flex items-center justify-center">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z"></path></svg>
             </div>
             <p className="text-sm italic">รอรับคำสั่ง...</p>
          </div>
        )}
        {logs.map((log, index) => (
          <div key={index} className="flex gap-3 items-start animate-fade-in group">
            <div className="min-w-[3.5rem] text-[10px] text-stone-400 mt-1.5 font-mono text-right group-hover:text-stone-600 transition-colors">
              {log.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
            </div>
            <div className="flex-1">
              <span className={`inline-block px-2.5 py-0.5 rounded-md text-[10px] font-bold mr-2 mb-1 shadow-sm ${getAgentColor(log.agent)}`}>
                {log.agent}
              </span>
              <p className="text-sm text-stone-700 leading-relaxed bg-stone-50/50 p-2 rounded-lg border border-transparent hover:border-stone-100 transition-all">
                {log.message}
              </p>
            </div>
          </div>
        ))}
        <div ref={bottomRef} />
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { EBook } from '../types';
import { marked } from 'marked';
import ReactMarkdown from 'react-markdown';
import { 
  ArrowDownTrayIcon, 
  PrinterIcon, 
  DocumentTextIcon, 
  CodeBracketIcon,
  PencilSquareIcon,
  XMarkIcon,
  CheckIcon,
  PhotoIcon,
  LinkIcon
} from '@heroicons/react/24/solid';

interface BookPreviewProps {
  ebook: EBook;
  onRestart: () => void;
  onUpdateChapter: (index: number, content: string) => void;
}

export const BookPreview: React.FC<BookPreviewProps> = ({ ebook, onRestart, onUpdateChapter }) => {
  const [activeChapter, setActiveChapter] = useState(0);

  // Edit State
  const [isEditing, setIsEditing] = useState(false);
  const [editingContent, setEditingContent] = useState('');
  const [editingIndex, setEditingIndex] = useState<number | null>(null);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const startEditing = (index: number, content: string) => {
    setEditingIndex(index);
    setEditingContent(content || "");
    setIsEditing(true);
  };

  const saveEditing = () => {
    if (editingIndex !== null) {
      onUpdateChapter(editingIndex, editingContent);
    }
    setIsEditing(false);
    setEditingIndex(null);
  };

  const cancelEditing = () => {
    setIsEditing(false);
    setEditingIndex(null);
  };

  const handleInsertImage = (url: string, alt: string = 'รูปภาพประกอบ') => {
      const imageMarkdown = `\n\n![${alt}](${url})\n\n`;

      if (textareaRef.current) {
          const start = textareaRef.current.selectionStart;
          const end = textareaRef.current.selectionEnd;
          const text = editingContent;
          const newText = text.substring(0, start) + imageMarkdown + text.substring(end);
          setEditingContent(newText);
      } else {
          setEditingContent(prev => prev + imageMarkdown);
      }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (event) => {
              if (event.target?.result) {
                  handleInsertImage(event.target.result as string, file.name);
              }
          };
          reader.readAsDataURL(file);
      }
      if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const downloadFile = (content: string, filename: string, type: string) => {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const getFullHTML = async () => {
    let bodyContent = '';

    if (ebook.coverImage) {
        bodyContent += `<div style="text-align:center; margin-bottom: 60px;"><img src="${ebook.coverImage}" style="max-width:100%; height:auto; border-radius: 12px; box-shadow: 0 10px 25px rgba(0,0,0,0.15);"></div>`;
    }
    bodyContent += `<h1 style="text-align:center; font-size: 3.5em; margin-bottom: 0.5em; color: #44403c;">${ebook.title}</h1>`;
    bodyContent += `<p style="text-align:center; font-size: 1.2em; color: #78716c; margin-bottom: 3em;">${ebook.targetAudience}</p>`;
    bodyContent += `<div style="text-align:center; font-style: italic; margin-bottom: 6em; padding: 40px; background: #fafaf9; border-radius: 16px; border: 1px solid #e7e5e4;">${ebook.description}</div>`;

    for (const chap of ebook.chapters) {
        bodyContent += `<div style="page-break-after: always; margin-bottom: 80px;">`;
        bodyContent += `<h2 style="font-size: 2.2em; border-bottom: 3px solid #f59e0b; padding-bottom: 15px; margin-bottom: 30px; color: #292524;">${chap.title}</h2>`;
        const htmlContent = await marked.parse(chap.content || '');
        bodyContent += `<div style="font-size: 1.15em; line-height: 1.9; color: #292524;">${htmlContent}</div>`;
        bodyContent += `</div>`;
    }

    return `
      <!DOCTYPE html>
      <html lang="th">
      <head>
          <meta charset="UTF-8">
          <meta name="viewport" content="width=device-width, initial-scale=1.0">
          <title>${ebook.title}</title>
          <link href="https://fonts.googleapis.com/css2?family=Sarabun:wght@300;400;600&display=swap" rel="stylesheet">
          <style>
              body { font-family: 'Sarabun', sans-serif; max-width: 800px; margin: 0 auto; padding: 60px; background-color: #ffffff; }
              img { max-width: 100%; height: auto; display: block; margin: 30px auto; border-radius: 8px; }
              h1, h2, h3 { font-weight: 700; }
              p { margin-bottom: 1.6em; }
              ul, ol { margin-bottom: 1.6em; padding-left: 24px; }
              li { margin-bottom: 0.8em; }
              blockquote { border-left: 5px solid #d6d3d1; padding-left: 20px; color: #57534e; font-style: italic; background: #fafaf9; padding: 15px 20px; border-radius: 0 8px 8px 0; }
              @media print {
                  body { max-width: 100%; padding: 0; }
              }
          </style>
      </head>
      <body>
          ${bodyContent}
      </body>
      </html>
    `;
  };

  const handleDownloadMarkdown = () => {
    let mdContent = `# ${ebook.title}\n\n`;
    mdContent += `> ${ebook.description}\n\n`;
    mdContent += `**กลุ่มเป้าหมาย:** ${ebook.targetAudience}\n\n`;
    mdContent += `---\n\n`;

    ebook.chapters.forEach(chap => {
        mdContent += `# ${chap.title}\n\n`;
        mdContent += `${chap.content}\n\n`;
        mdContent += `---\n\n`;
    });

    downloadFile(mdContent, `${ebook.title}.md`, 'text/markdown');
  };

  const handleDownloadHTML = async () => {
    const html = await getFullHTML();
    downloadFile(html, `${ebook.title}.html`, 'text/html');
  };

  const handlePrintPDF = async () => {
    const html = await getFullHTML();
    const printWindow = window.open('', '_blank');
    if (printWindow) {
        printWindow.document.write(html);
        printWindow.document.close();
        printWindow.focus();
        setTimeout(() => {
            printWindow.print();
        }, 500);
    }
  };

  return (
    <div className="flex flex-col lg:flex-row gap-8 h-full relative animate-fade-in">

      {/* Edit Modal Overlay */}
      {isEditing && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-stone-900/60 backdrop-blur-md">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl h-[85vh] flex flex-col border border-stone-200 overflow-hidden">
            <div className="p-4 border-b border-stone-100 flex justify-between items-center bg-stone-50">
              <h3 className="font-bold text-stone-800 flex items-center gap-2">
                <PencilSquareIcon className="w-5 h-5 text-amber-600" /> 
                แก้ไขเนื้อหา: {editingIndex !== null && ebook.chapters[editingIndex]?.title}
              </h3>
              <button onClick={cancelEditing} className="text-stone-400 hover:text-stone-600 transition-colors bg-white p-1 rounded-full border border-stone-200 hover:bg-stone-100">
                <XMarkIcon className="w-6 h-6" />
              </button>
            </div>

            {/* Toolbar */}
            <div className="bg-stone-50 border-b border-stone-200 px-4 py-2 flex items-center gap-2">
                <span className="text-xs font-semibold text-stone-500 mr-2">แทรกสื่อ:</span>
                <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-stone-300 rounded-lg text-xs font-medium text-stone-700 hover:bg-amber-50 hover:text-amber-700 hover:border-amber-300 transition-colors shadow-sm"
                >
                    <PhotoIcon className="w-4 h-4" /> อัปโหลดรูป
                </button>
                <button 
                    onClick={() => {
                        const url = prompt("กรุณาระบุ URL ของรูปภาพ:");
                        if (url) handleInsertImage(url);
                    }}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-stone-300 rounded-lg text-xs font-medium text-stone-700 hover:bg-amber-50 hover:text-amber-700 hover:border-amber-300 transition-colors shadow-sm"
                >
                    <LinkIcon className="w-4 h-4" /> จาก URL
                </button>
                <input 
                    type="file" 
                    ref={fileInputRef} 
                    onChange={handleFileUpload} 
                    className="hidden" 
                    accept="image/*"
                />
            </div>

            <div className="flex-1 p-0 relative bg-stone-50/30">
              <textarea
                ref={textareaRef}
                value={editingContent}
                onChange={(e) => setEditingContent(e.target.value)}
                className="w-full h-full p-8 resize-none focus:outline-none text-stone-800 leading-relaxed font-mono text-sm bg-transparent"
                placeholder="เขียนเนื้อหาที่นี่... รองรับ Markdown"
              />
            </div>

            <div className="p-4 border-t border-stone-100 flex justify-end gap-3 bg-stone-50">
              <button 
                onClick={cancelEditing}
                className="px-5 py-2.5 text-stone-600 hover:bg-stone-200 rounded-xl font-medium transition-colors"
              >
                ยกเลิก
              </button>
              <button 
                onClick={saveEditing}
