                    className="flex-1 py-2.5 px-2 bg-white border border-stone-200 rounded-xl text-stone-700 hover:bg-amber-50 hover:border-amber-300 hover:text-amber-800 transition-all text-sm font-medium flex items-center justify-center gap-2 shadow-sm"
