import React, { useState, useRef } from 'react';
import { EBook } from '../types';
import { marked } from 'marked';
import ReactMarkdown from 'react-markdown';
import { 
  ArrowDownTrayIcon, 
  PrinterIcon, 
  DocumentTextIcon, 
  CodeBracketIcon,
  PencilSquareIcon,
  XMarkIcon,
  CheckIcon,
  PhotoIcon,
  LinkIcon,
  ArrowPathIcon,
  BookOpenIcon
} from '@heroicons/react/24/solid';

interface BookPreviewProps {
  ebook: EBook;
  onRestart: () => void;
  onUpdateChapter: (index: number, content: string) => void;
}

export const BookPreview: React.FC<BookPreviewProps> = ({ ebook, onRestart, onUpdateChapter }) => {
  const [activeChapter, setActiveChapter] = useState(0);

  // Edit State
  const [isEditing, setIsEditing] = useState(false);
  const [editingContent, setEditingContent] = useState('');
  const [editingIndex, setEditingIndex] = useState<number | null>(null);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const startEditing = (index: number, content: string) => {
    setEditingIndex(index);
    setEditingContent(content || "");
    setIsEditing(true);
  };

  const saveEditing = () => {
    if (editingIndex !== null) {
      onUpdateChapter(editingIndex, editingContent);
    }
    setIsEditing(false);
    setEditingIndex(null);
  };

  const cancelEditing = () => {
    setIsEditing(false);
    setEditingIndex(null);
  };

  const handleInsertImage = (url: string, alt: string = 'รูปภาพประกอบ') => {
      const imageMarkdown = `\n\n![${alt}](${url})\n\n`;

      if (textareaRef.current) {
          const start = textareaRef.current.selectionStart;
          const end = textareaRef.current.selectionEnd;
          const text = editingContent;
          const newText = text.substring(0, start) + imageMarkdown + text.substring(end);
          setEditingContent(newText);
      } else {
          setEditingContent(prev => prev + imageMarkdown);
      }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (event) => {
              if (event.target?.result) {
                  handleInsertImage(event.target.result as string, file.name);
              }
          };
          reader.readAsDataURL(file);
      }
      if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const downloadFile = (content: string, filename: string, type: string) => {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const getFullHTML = async () => {
    let bodyContent = '';

    if (ebook.coverImage) {
        bodyContent += `<div style="text-align:center; margin-bottom: 60px;"><img src="${ebook.coverImage}" style="max-width:100%; height:auto; border-radius: 12px; box-shadow: 0 10px 25px rgba(0,0,0,0.15);"></div>`;
    }
    bodyContent += `<h1 style="text-align:center; font-size: 3.5em; margin-bottom: 0.5em; color: #44403c;">${ebook.title}</h1>`;
    bodyContent += `<p style="text-align:center; font-size: 1.2em; color: #78716c; margin-bottom: 3em;">${ebook.targetAudience}</p>`;
    bodyContent += `<div style="text-align:center; font-style: italic; margin-bottom: 6em; padding: 40px; background: #fafaf9; border-radius: 16px; border: 1px solid #e7e5e4;">${ebook.description}</div>`;

    for (const chap of ebook.chapters) {
        bodyContent += `<div style="page-break-after: always; margin-bottom: 80px;">`;
        bodyContent += `<h2 style="font-size: 2.2em; border-bottom: 3px solid #f59e0b; padding-bottom: 15px; margin-bottom: 30px; color: #292524;">${chap.title}</h2>`;
        const htmlContent = await marked.parse(chap.content || '');
        bodyContent += `<div style="font-size: 1.15em; line-height: 1.9; color: #292524;">${htmlContent}</div>`;
        bodyContent += `</div>`;
    }

    return `
      <!DOCTYPE html>
      <html lang="th">
      <head>
          <meta charset="UTF-8">
          <meta name="viewport" content="width=device-width, initial-scale=1.0">
          <title>${ebook.title}</title>
          <link href="https://fonts.googleapis.com/css2?family=Sarabun:wght@300;400;600&display=swap" rel="stylesheet">
          <style>
              body { font-family: 'Sarabun', sans-serif; max-width: 800px; margin: 0 auto; padding: 60px; background-color: #ffffff; }
              img { max-width: 100%; height: auto; display: block; margin: 30px auto; border-radius: 8px; }
              h1, h2, h3 { font-weight: 700; }
              p { margin-bottom: 1.6em; }
              ul, ol { margin-bottom: 1.6em; padding-left: 24px; }
              li { margin-bottom: 0.8em; }
              blockquote { border-left: 5px solid #d6d3d1; padding-left: 20px; color: #57534e; font-style: italic; background: #fafaf9; padding: 15px 20px; border-radius: 0 8px 8px 0; }
              @media print {
                  body { max-width: 100%; padding: 0; }
              }
          </style>
      </head>
      <body>
          ${bodyContent}
      </body>
      </html>
    `;
  };

  const handleDownloadMarkdown = () => {
    let mdContent = `# ${ebook.title}\n\n`;
    mdContent += `> ${ebook.description}\n\n`;
    mdContent += `**กลุ่มเป้าหมาย:** ${ebook.targetAudience}\n\n`;
    mdContent += `---\n\n`;

    ebook.chapters.forEach(chap => {
        mdContent += `# ${chap.title}\n\n`;
        mdContent += `${chap.content}\n\n`;
        mdContent += `---\n\n`;
    });

    downloadFile(mdContent, `${ebook.title}.md`, 'text/markdown');
  };

  const handleDownloadHTML = async () => {
    const html = await getFullHTML();
    downloadFile(html, `${ebook.title}.html`, 'text/html');
  };

  const handlePrintPDF = async () => {
    const html = await getFullHTML();
    const printWindow = window.open('', '_blank');
    if (printWindow) {
        printWindow.document.write(html);
        printWindow.document.close();
        printWindow.focus();
        setTimeout(() => {
            printWindow.print();
        }, 500);
    }
  };

  return (
    <div className="flex flex-col lg:flex-row gap-8 h-full relative animate-fade-in">

      {/* Edit Modal Overlay */}
      {isEditing && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-stone-900/60 backdrop-blur-md">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl h-[85vh] flex flex-col border border-stone-200 overflow-hidden">
            <div className="p-4 border-b border-stone-100 flex justify-between items-center bg-stone-50">
              <h3 className="font-bold text-stone-800 flex items-center gap-2">
                <PencilSquareIcon className="w-5 h-5 text-amber-600" /> 
                แก้ไขเนื้อหา: {editingIndex !== null && ebook.chapters[editingIndex]?.title}
              </h3>
              <button onClick={cancelEditing} className="text-stone-400 hover:text-stone-600 transition-colors bg-white p-1 rounded-full border border-stone-200 hover:bg-stone-100">
                <XMarkIcon className="w-6 h-6" />
              </button>
            </div>

            {/* Toolbar */}
            <div className="bg-stone-50 border-b border-stone-200 px-4 py-2 flex items-center gap-2">
                <span className="text-xs font-semibold text-stone-500 mr-2">แทรกสื่อ:</span>
                <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-stone-300 rounded-lg text-xs font-medium text-stone-700 hover:bg-amber-50 hover:text-amber-700 hover:border-amber-300 transition-colors shadow-sm"
                >
                    <PhotoIcon className="w-4 h-4" /> อัปโหลดรูป
                </button>
                <button 
                    onClick={() => {
                        const url = prompt("กรุณาระบุ URL ของรูปภาพ:");
                        if (url) handleInsertImage(url);
                    }}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-stone-300 rounded-lg text-xs font-medium text-stone-700 hover:bg-amber-50 hover:text-amber-700 hover:border-amber-300 transition-colors shadow-sm"
                >
                    <LinkIcon className="w-4 h-4" /> จาก URL
                </button>
                <input 
                    type="file" 
                    ref={fileInputRef} 
                    onChange={handleFileUpload} 
                    className="hidden" 
                    accept="image/*"
                />
            </div>

            <div className="flex-1 p-0 relative bg-stone-50/30">
              <textarea
                ref={textareaRef}
                value={editingContent}
                onChange={(e) => setEditingContent(e.target.value)}
                className="w-full h-full p-8 resize-none focus:outline-none text-stone-800 leading-relaxed font-mono text-sm bg-transparent"
                placeholder="เขียนเนื้อหาที่นี่... รองรับ Markdown"
              />
            </div>

            <div className="p-4 border-t border-stone-100 flex justify-end gap-3 bg-stone-50">
              <button 
                onClick={cancelEditing}
                className="px-5 py-2.5 text-stone-600 hover:bg-stone-200 rounded-xl font-medium transition-colors"
              >
                ยกเลิก
              </button>
              <button 
                onClick={saveEditing}
                className="px-6 py-2.5 bg-amber-600 text-white hover:bg-amber-700 rounded-xl font-bold shadow-lg shadow-amber-200 flex items-center gap-2 transition-colors"
              >
                <CheckIcon className="w-5 h-5" /> บันทึกการแก้ไข
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Sidebar / Cover */}
      <div className="w-full lg:w-1/3 flex flex-col gap-6">
        <div className="bg-white p-5 rounded-2xl shadow-lg border border-stone-200 transform hover:scale-[1.02] transition-transform duration-300 relative group">
            <div className="absolute inset-0 bg-gradient-to-tr from-amber-500/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity rounded-2xl pointer-events-none"></div>
            {ebook.coverImage ? (
                <img 
                    src={ebook.coverImage} 
                    alt="Book Cover" 
                    className="w-full rounded-lg shadow-md aspect-[3/4] object-cover"
                />
            ) : (
                <div className="w-full aspect-[3/4] bg-stone-100 rounded-lg flex flex-col items-center justify-center text-stone-400 gap-2 border-2 border-dashed border-stone-200">
                   <PhotoIcon className="w-12 h-12 opacity-50" />
                   <span>ไม่มีรูปปก</span>
                </div>
            )}
        </div>

        <div className="bg-white/80 backdrop-blur-sm p-6 rounded-2xl shadow-sm border border-stone-200">
            <h1 className="text-2xl font-bold text-stone-800 mb-2 font-promt">{ebook.title}</h1>
            <p className="text-sm text-stone-500 mb-4 bg-stone-100 inline-block px-2 py-1 rounded-md">{ebook.targetAudience}</p>
            <p className="text-stone-700 text-sm italic leading-relaxed">{ebook.description}</p>
        </div>

        {/* Export Actions */}
        <div className="bg-white/60 p-5 rounded-2xl border border-stone-200 space-y-3 shadow-sm">
            <h3 className="font-semibold text-stone-700 text-sm mb-2 flex items-center gap-2">
                <ArrowDownTrayIcon className="w-4 h-4 text-amber-600" /> ดาวน์โหลด / Export
            </h3>

            <button 
                onClick={handlePrintPDF}
                className="w-full py-2.5 px-4 bg-white border border-stone-200 rounded-xl text-stone-700 hover:bg-amber-50 hover:border-amber-300 hover:text-amber-800 transition-all text-sm font-medium flex items-center justify-center gap-2 shadow-sm"
            >
                <PrinterIcon className="w-4 h-4" /> บันทึกเป็น PDF (Print)
            </button>

            <div className="flex gap-2">
                <button 
                    onClick={handleDownloadHTML}
                    className="flex-1 py-2.5 px-2 bg-white border border-stone-200 rounded-xl text-stone-700 hover:bg-amber-50 hover:border-amber-300 hover:text-amber-800 transition-all text-sm font-medium flex items-center justify-center gap-2 shadow-sm"
                >
                    <CodeBracketIcon className="w-4 h-4" /> HTML
                </button>
                <button 
                    onClick={handleDownloadMarkdown}
                    className="flex-1 py-2.5 px-2 bg-white border border-stone-200 rounded-xl text-stone-700 hover:bg-amber-50 hover:border-amber-300 hover:text-amber-800 transition-all text-sm font-medium flex items-center justify-center gap-2 shadow-sm"
                >
                    <DocumentTextIcon className="w-4 h-4" /> Markdown
                </button>
            </div>
            <p className="text-[10px] text-stone-400 text-center pt-1">
                *ไฟล์ Markdown/HTML สามารถนำไปแปลงเป็น EPUB ได้
            </p>
        </div>

        <button 
            onClick={onRestart}
            className="w-full py-3.5 bg-stone-800 text-white rounded-xl hover:bg-stone-900 transition-all font-medium mt-auto shadow-lg shadow-stone-300 flex justify-center items-center gap-2"
        >
            <ArrowPathIcon className="w-4 h-4" /> เริ่มโปรเจกต์ใหม่
        </button>
      </div>

      {/* Content Reader */}
      <div className="w-full lg:w-2/3 bg-white rounded-3xl shadow-xl shadow-stone-200/50 border border-stone-100 flex flex-col h-[850px] overflow-hidden">
        {/* Reader Header */}
        <div className="p-5 border-b border-stone-100 flex justify-between items-center bg-stone-50/50">
            <h2 className="font-bold text-stone-700 flex items-center gap-2">
                <BookOpenIcon className="w-5 h-5 text-amber-600" /> 
                ตัวอย่างเนื้อหาหนังสือ
            </h2>
            <div className="text-sm text-stone-500 bg-white px-3 py-1 rounded-full border border-stone-200 shadow-sm">
                {ebook.chapters[activeChapter].id === 'ch-conclusion' 
                    ? 'บทส่งท้าย' 
                    : `บทที่ ${activeChapter + 1}`} 
                <span className="text-stone-300 mx-2">|</span>
                {ebook.chapters.length} ส่วน
            </div>
        </div>

        <div className="flex flex-1 overflow-hidden">
            {/* TOC */}
            <div className="w-1/3 border-r border-stone-100 overflow-y-auto bg-stone-50/30 custom-scrollbar">
                <ul className="divide-y divide-stone-100">
                    {ebook.chapters.map((chapter, idx) => (
                        <li key={chapter.id} className="group relative hover:bg-amber-50/50 transition-colors">
                            <button
                                onClick={() => setActiveChapter(idx)}
                                className={`w-full text-left p-5 text-sm pr-12 transition-all ${activeChapter === idx ? 'bg-white text-amber-800 font-semibold border-l-4 border-amber-500 shadow-sm' : 'text-stone-600'}`}
                            >
                                <span className="block text-xs text-stone-400 mb-1 uppercase tracking-wider">
                                    {chapter.id === 'ch-conclusion' ? 'บทส่งท้าย' : `บทที่ ${idx + 1}`}
                                </span>
                                {chapter.title}
                            </button>
                            {/* Edit Button */}
                            <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  startEditing(idx, chapter.content || "");
                                }}
                                className="absolute right-3 top-1/2 -translate-y-1/2 p-1.5 text-stone-300 hover:text-amber-600 hover:bg-amber-100 rounded-lg transition-all opacity-0 group-hover:opacity-100"
                                title="แก้ไขเนื้อหา"
                            >
                                <PencilSquareIcon className="w-4 h-4" />
                            </button>
                        </li>
                    ))}
                </ul>
            </div>

            {/* Content */}
            <div className="w-2/3 overflow-y-auto p-10 bg-white custom-scrollbar">
                <h2 className="text-3xl font-bold text-stone-800 mb-8 border-b-2 border-amber-100 pb-6 font-promt leading-tight">
                    {ebook.chapters[activeChapter].title}
                </h2>
                <div className="prose prose-stone prose-lg max-w-none text-stone-700 leading-relaxed font-sarabun">
                    <ReactMarkdown components={{
                      img: ({node, ...props}) => <img style={{maxWidth: '100%', borderRadius: '12px', margin: '30px auto', display:'block', boxShadow: '0 4px 12px rgba(0,0,0,0.08)'}} {...props} />,
                      h2: ({node, ...props}) => <h2 className="text-amber-800 font-bold mt-8 mb-4" {...props} />,
                      h3: ({node, ...props}) => <h3 className="text-stone-800 font-semibold mt-6 mb-3" {...props} />,
                      blockquote: ({node, ...props}) => <blockquote className="border-l-4 border-amber-300 bg-amber-50 p-4 italic rounded-r-lg my-6 text-stone-600" {...props} />
                    }}>
                        {ebook.chapters[activeChapter].content || "ยังไม่มีเนื้อหา"}
                    </ReactMarkdown>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { EBook } from '../types';
import { marked } from 'marked';
import ReactMarkdown from 'react-markdown';
import JSZip from 'jszip';
import { 
  ArrowDownTrayIcon, 
  PrinterIcon, 
  DocumentTextIcon, 
  CodeBracketIcon,
  PencilSquareIcon,
  XMarkIcon,
  CheckIcon,
  PhotoIcon,
  LinkIcon,
  ArrowPathIcon,
  BookOpenIcon
} from '@heroicons/react/24/solid';

interface BookPreviewProps {
  ebook: EBook;
  onRestart: () => void;
  onUpdateChapter: (index: number, content: string) => void;
}

export const BookPreview: React.FC<BookPreviewProps> = ({ ebook, onRestart, onUpdateChapter }) => {
  const [activeChapter, setActiveChapter] = useState(0);
  const [isExportingEPUB, setIsExportingEPUB] = useState(false);

  // Edit State
  const [isEditing, setIsEditing] = useState(false);
  const [editingContent, setEditingContent] = useState('');
  const [editingIndex, setEditingIndex] = useState<number | null>(null);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const startEditing = (index: number, content: string) => {
    setEditingIndex(index);
    setEditingContent(content || "");
    setIsEditing(true);
  };

  const saveEditing = () => {
    if (editingIndex !== null) {
      onUpdateChapter(editingIndex, editingContent);
    }
    setIsEditing(false);
    setEditingIndex(null);
  };

  const cancelEditing = () => {
    setIsEditing(false);
    setEditingIndex(null);
  };

  const handleInsertImage = (url: string, alt: string = 'รูปภาพประกอบ') => {
      const imageMarkdown = `\n\n![${alt}](${url})\n\n`;

      if (textareaRef.current) {
          const start = textareaRef.current.selectionStart;
          const end = textareaRef.current.selectionEnd;
          const text = editingContent;
          const newText = text.substring(0, start) + imageMarkdown + text.substring(end);
          setEditingContent(newText);
      } else {
          setEditingContent(prev => prev + imageMarkdown);
      }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (event) => {
              if (event.target?.result) {
                  handleInsertImage(event.target.result as string, file.name);
              }
          };
          reader.readAsDataURL(file);
      }
      if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const downloadFile = (content: string, filename: string, type: string) => {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const getFullHTML = async () => {
    let bodyContent = '';

    if (ebook.coverImage) {
        bodyContent += `<div style="text-align:center; margin-bottom: 60px;"><img src="${ebook.coverImage}" style="max-width:100%; height:auto; border-radius: 12px; box-shadow: 0 10px 25px rgba(0,0,0,0.15);"></div>`;
    }
    bodyContent += `<h1 style="text-align:center; font-size: 3.5em; margin-bottom: 0.5em; color: #44403c;">${ebook.title}</h1>`;
    bodyContent += `<p style="text-align:center; font-size: 1.2em; color: #78716c; margin-bottom: 3em;">${ebook.targetAudience}</p>`;
    bodyContent += `<div style="text-align:center; font-style: italic; margin-bottom: 6em; padding: 40px; background: #fafaf9; border-radius: 16px; border: 1px solid #e7e5e4;">${ebook.description}</div>`;

    for (const chap of ebook.chapters) {
        bodyContent += `<div style="page-break-after: always; margin-bottom: 80px;">`;
        bodyContent += `<h2 style="font-size: 2.2em; border-bottom: 3px solid #f59e0b; padding-bottom: 15px; margin-bottom: 30px; color: #292524;">${chap.title}</h2>`;
        const htmlContent = await marked.parse(chap.content || '');
        bodyContent += `<div style="font-size: 1.15em; line-height: 1.9; color: #292524;">${htmlContent}</div>`;
        bodyContent += `</div>`;
    }

    return `
      <!DOCTYPE html>
      <html lang="th">
      <head>
          <meta charset="UTF-8">
          <meta name="viewport" content="width=device-width, initial-scale=1.0">
          <title>${ebook.title}</title>
          <link href="https://fonts.googleapis.com/css2?family=Sarabun:wght@300;400;600&display=swap" rel="stylesheet">
          <style>
              body { font-family: 'Sarabun', sans-serif; max-width: 800px; margin: 0 auto; padding: 60px; background-color: #ffffff; }
              img { max-width: 100%; height: auto; display: block; margin: 30px auto; border-radius: 8px; }
              h1, h2, h3 { font-weight: 700; }
              p { margin-bottom: 1.6em; }
              ul, ol { margin-bottom: 1.6em; padding-left: 24px; }
              li { margin-bottom: 0.8em; }
              blockquote { border-left: 5px solid #d6d3d1; padding-left: 20px; color: #57534e; font-style: italic; background: #fafaf9; padding: 15px 20px; border-radius: 0 8px 8px 0; }
              @media print {
                  body { max-width: 100%; padding: 0; }
              }
          </style>
      </head>
      <body>
          ${bodyContent}
      </body>
      </html>
    `;
  };

  const handleDownloadMarkdown = () => {
    let mdContent = `# ${ebook.title}\n\n`;
    mdContent += `> ${ebook.description}\n\n`;
    mdContent += `**กลุ่มเป้าหมาย:** ${ebook.targetAudience}\n\n`;
    mdContent += `---\n\n`;

    ebook.chapters.forEach(chap => {
        mdContent += `# ${chap.title}\n\n`;
        mdContent += `${chap.content}\n\n`;
        mdContent += `---\n\n`;
    });

    downloadFile(mdContent, `${ebook.title}.md`, 'text/markdown');
  };

  const handleDownloadHTML = async () => {
    const html = await getFullHTML();
    downloadFile(html, `${ebook.title}.html`, 'text/html');
  };

  const handleDownloadEPUB = async () => {
    setIsExportingEPUB(true);
    try {
        const zip = new JSZip();

        // 1. mimetype
        zip.file("mimetype", "application/epub+zip");

        // 2. META-INF/container.xml
        zip.folder("META-INF")?.file("container.xml", `<?xml version="1.0"?>
<container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container">
   <rootfiles>
      <rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml"/>
   </rootfiles>
</container>`);

        // 3. OEBPS folder
        const oebps = zip.folder("OEBPS");
        if(!oebps) return;

        // CSS
        oebps.file("style.css", `
            body { font-family: 'Sarabun', sans-serif; line-height: 1.6; color: #333; }
            h1, h2, h3 { color: #d97706; margin-top: 1em; margin-bottom: 0.5em; }
            img { max-width: 100%; height: auto; display: block; margin: 1em auto; }
            blockquote { border-left: 4px solid #d97706; padding-left: 1em; color: #666; font-style: italic; margin: 1em 0; }
            p { margin-bottom: 1em; }
        `);

        let manifest = '';
        let spine = '';
        let navMap = '';

        // Title Page
        const titlePageContent = `<?xml version="1.0" encoding="utf-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml">
<head><title>${ebook.title}</title><link rel="stylesheet" type="text/css" href="style.css"/></head>
<body>
  <div style="text-align:center; margin-top: 50px;">
    ${ebook.coverImage ? `<img src="cover.jpg" alt="Cover" style="max-height: 800px;"/>` : ''}
    <h1>${ebook.title}</h1>
    <p>${ebook.targetAudience}</p>
    <p><i>${ebook.description}</i></p>
  </div>
</body>
</html>`;
        oebps.file("title.xhtml", titlePageContent);
        manifest += `<item id="title" href="title.xhtml" media-type="application/xhtml+xml"/>\n`;
        spine += `<itemref idref="title"/>\n`;
        navMap += `<navPoint id="navPoint-0" playOrder="0"><navLabel><text>Title Page</text></navLabel><content src="title.xhtml"/></navPoint>\n`;

        // Cover Image
        if (ebook.coverImage) {
            try {
                const response = await fetch(ebook.coverImage);
                const blob = await response.blob();
                oebps.file("cover.jpg", blob);
                manifest += `<item id="cover-img" href="cover.jpg" media-type="image/jpeg"/>\n`;
            } catch (e) {
                console.warn("Could not fetch cover image for EPUB", e);
            }
        }

        // Chapters
        for (let i = 0; i < ebook.chapters.length; i++) {
            const chap = ebook.chapters[i];
            const htmlContent = await marked.parse(chap.content || '');
            const filename = `chapter-${i+1}.xhtml`;
            const fileContent = `<?xml version="1.0" encoding="utf-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml">
<head><title>${chap.title}</title><link rel="stylesheet" type="text/css" href="style.css"/></head>
<body>
  <h2>${chap.title}</h2>
  <div>${htmlContent}</div>
</body>
</html>`;
            oebps.file(filename, fileContent);

            const id = `chap${i+1}`;
            manifest += `<item id="${id}" href="${filename}" media-type="application/xhtml+xml"/>\n`;
            spine += `<itemref idref="${id}"/>\n`;
            navMap += `<navPoint id="navPoint-${i+1}" playOrder="${i+1}"><navLabel><text>${chap.title}</text></navLabel><content src="${filename}"/></navPoint>\n`;
        }

        // toc.ncx
        oebps.file("toc.ncx", `<?xml version="1.0" encoding="UTF-8"?>
<ncx xmlns="http://www.daisy.org/z3986/2005/ncx/" version="2005-1">
<head><meta name="dtb:uid" content="urn:uuid:12345"/></head>
<docTitle><text>${ebook.title}</text></docTitle>
<navMap>
  ${navMap}
</navMap>
</ncx>`);

        // content.opf
        oebps.file("content.opf", `<?xml version="1.0" encoding="utf-8"?>
<package xmlns="http://www.idpf.org/2007/opf" unique-identifier="BookId" version="2.0">
    <metadata xmlns:dc="http://purl.org/dc/elements/1.1/">
        <dc:title>${ebook.title}</dc:title>
        <dc:language>th</dc:language>
        <dc:identifier id="BookId">urn:uuid:12345</dc:identifier>
        <meta name="cover" content="cover-img"/>
    </metadata>
    <manifest>
        <item id="ncx" href="toc.ncx" media-type="application/x-dtbncx+xml"/>
        <item id="css" href="style.css" media-type="text/css"/>
        ${manifest}
    </manifest>
    <spine toc="ncx">
        ${spine}
    </spine>
</package>`);

        const content = await zip.generateAsync({type: "blob"});
        const url = URL.createObjectURL(content);
        const link = document.createElement('a');
        link.href = url;
        link.download = `${ebook.title}.epub`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);

    } catch (e) {
        console.error("EPUB Generation Error", e);
        alert("ไม่สามารถสร้างไฟล์ EPUB ได้ในขณะนี้");
    } finally {
        setIsExportingEPUB(false);
    }
  };

  const handlePrintPDF = async () => {
    const html = await getFullHTML();
    const printWindow = window.open('', '_blank');
    if (printWindow) {
        printWindow.document.write(html);
        printWindow.document.close();
        printWindow.focus();
        setTimeout(() => {
            printWindow.print();
        }, 500);
    }
  };

  return (
    <div className="flex flex-col lg:flex-row gap-8 h-full relative animate-fade-in">

      {/* Edit Modal Overlay */}
      {isEditing && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-stone-900/60 backdrop-blur-md">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl h-[85vh] flex flex-col border border-stone-200 overflow-hidden">
            <div className="p-4 border-b border-stone-100 flex justify-between items-center bg-stone-50">
              <h3 className="font-bold text-stone-800 flex items-center gap-2">
                <PencilSquareIcon className="w-5 h-5 text-amber-600" /> 
                แก้ไขเนื้อหา: {editingIndex !== null && ebook.chapters[editingIndex]?.title}
              </h3>
              <button onClick={cancelEditing} className="text-stone-400 hover:text-stone-600 transition-colors bg-white p-1 rounded-full border border-stone-200 hover:bg-stone-100">
                <XMarkIcon className="w-6 h-6" />
              </button>
            </div>

            {/* Toolbar */}
            <div className="bg-stone-50 border-b border-stone-200 px-4 py-2 flex items-center gap-2">
                <span className="text-xs font-semibold text-stone-500 mr-2">แทรกสื่อ:</span>
                <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-stone-300 rounded-lg text-xs font-medium text-stone-700 hover:bg-amber-50 hover:text-amber-700 hover:border-amber-300 transition-colors shadow-sm"
                >
                    <PhotoIcon className="w-4 h-4" /> อัปโหลดรูป
                </button>
                <button 
                    onClick={() => {
                        const url = prompt("กรุณาระบุ URL ของรูปภาพ:");
                        if (url) handleInsertImage(url);
                    }}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-stone-300 rounded-lg text-xs font-medium text-stone-700 hover:bg-amber-50 hover:text-amber-700 hover:border-amber-300 transition-colors shadow-sm"
                >
                    <LinkIcon className="w-4 h-4" /> จาก URL
                </button>
                <input 
                    type="file" 
                    ref={fileInputRef} 
                    onChange={handleFileUpload} 
                    className="hidden" 
                    accept="image/*"
                />
            </div>

            <div className="flex-1 p-0 relative bg-stone-50/30">
              <textarea
                ref={textareaRef}
                value={editingContent}
                onChange={(e) => setEditingContent(e.target.value)}
                className="w-full h-full p-8 resize-none focus:outline-none text-stone-800 leading-relaxed font-mono text-sm bg-transparent"
                placeholder="เขียนเนื้อหาที่นี่... รองรับ Markdown"
              />
            </div>

            <div className="p-4 border-t border-stone-100 flex justify-end gap-3 bg-stone-50">
              <button 
                onClick={cancelEditing}
                className="px-5 py-2.5 text-stone-600 hover:bg-stone-200 rounded-xl font-medium transition-colors"
              >
                ยกเลิก
              </button>
              <button 
                onClick={saveEditing}
                className="px-6 py-2.5 bg-amber-600 text-white hover:bg-amber-700 rounded-xl font-bold shadow-lg shadow-amber-200 flex items-center gap-2 transition-colors"
              >
                <CheckIcon className="w-5 h-5" /> บันทึกการแก้ไข
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Sidebar / Cover */}
      <div className="w-full lg:w-1/3 flex flex-col gap-6">
        <div className="bg-white p-5 rounded-2xl shadow-lg border border-stone-200 transform hover:scale-[1.02] transition-transform duration-300 relative group">
            <div className="absolute inset-0 bg-gradient-to-tr from-amber-500/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity rounded-2xl pointer-events-none"></div>
            {ebook.coverImage ? (
                <img 
                    src={ebook.coverImage} 
                    alt="Book Cover" 
                    className="w-full rounded-lg shadow-md aspect-[3/4] object-cover"
                />
            ) : (
                <div className="w-full aspect-[3/4] bg-stone-100 rounded-lg flex flex-col items-center justify-center text-stone-400 gap-2 border-2 border-dashed border-stone-200">
                   <PhotoIcon className="w-12 h-12 opacity-50" />
                   <span>ไม่มีรูปปก</span>
                </div>
            )}
        </div>

        <div className="bg-white/80 backdrop-blur-sm p-6 rounded-2xl shadow-sm border border-stone-200">
            <h1 className="text-2xl font-bold text-stone-800 mb-2 font-promt">{ebook.title}</h1>
            <p className="text-sm text-stone-500 mb-4 bg-stone-100 inline-block px-2 py-1 rounded-md">{ebook.targetAudience}</p>
            <p className="text-stone-700 text-sm italic leading-relaxed">{ebook.description}</p>
        </div>

        {/* Export Actions */}
        <div className="bg-white/60 p-5 rounded-2xl border border-stone-200 space-y-3 shadow-sm">
            <h3 className="font-semibold text-stone-700 text-sm mb-2 flex items-center gap-2">
                <ArrowDownTrayIcon className="w-4 h-4 text-amber-600" /> ดาวน์โหลด / Export
            </h3>

            <button 
                onClick={handleDownloadEPUB}
                disabled={isExportingEPUB}
                className="w-full py-2.5 px-4 bg-amber-600 text-white border border-amber-600 rounded-xl hover:bg-amber-700 transition-all text-sm font-bold flex items-center justify-center gap-2 shadow-md shadow-amber-200 disabled:opacity-50 disabled:cursor-wait"
            >
                {isExportingEPUB ? (
                    <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
                ) : (
                    <BookOpenIcon className="w-4 h-4" /> 
                )}
                บันทึกเป็น EPUB
            </button>

            <button 
                onClick={handlePrintPDF}
                className="w-full py-2.5 px-4 bg-white border border-stone-200 rounded-xl text-stone-700 hover:bg-amber-50 hover:border-amber-300 hover:text-amber-800 transition-all text-sm font-medium flex items-center justify-center gap-2 shadow-sm"
            >
                <PrinterIcon className="w-4 h-4" /> บันทึกเป็น PDF (Print)
            </button>

            <div className="flex gap-2">
                <button 
                    onClick={handleDownloadHTML}
                    className="flex-1 py-2.5 px-2 bg-white border border-stone-200 rounded-xl text-stone-700 hover:bg-amber-50 hover:border-amber-300 hover:text-amber-800 transition-all text-sm font-medium flex items-center justify-center gap-2 shadow-sm"
                >
                    <CodeBracketIcon className="w-4 h-4" /> HTML
                </button>
                <button 
                    onClick={handleDownloadMarkdown}
                    className="flex-1 py-2.5 px-2 bg-white border border-stone-200 rounded-xl text-stone-700 hover:bg-amber-50 hover:border-amber-300 hover:text-amber-800 transition-all text-sm font-medium flex items-center justify-center gap-2 shadow-sm"
                >
                    <DocumentTextIcon className="w-4 h-4" /> Markdown
                </button>
            </div>
            <p className="text-[10px] text-stone-400 text-center pt-1">
                *ไฟล์ EPUB สามารถเปิดอ่านได้ใน iBooks หรือ E-Reader ทั่วไป
            </p>
        </div>

        <button 
            onClick={onRestart}
            className="w-full py-3.5 bg-stone-800 text-white rounded-xl hover:bg-stone-900 transition-all font-medium mt-auto shadow-lg shadow-stone-300 flex justify-center items-center gap-2"
        >
            <ArrowPathIcon className="w-4 h-4" /> เริ่มโปรเจกต์ใหม่
        </button>
      </div>

      {/* Content Reader */}
      <div className="w-full lg:w-2/3 bg-white rounded-3xl shadow-xl shadow-stone-200/50 border border-stone-100 flex flex-col h-[850px] overflow-hidden">
        {/* Reader Header */}
        <div className="p-5 border-b border-stone-100 flex justify-between items-center bg-stone-50/50">
            <h2 className="font-bold text-stone-700 flex items-center gap-2">
                <BookOpenIcon className="w-5 h-5 text-amber-600" /> 
                ตัวอย่างเนื้อหาหนังสือ
            </h2>
            <div className="text-sm text-stone-500 bg-white px-3 py-1 rounded-full border border-stone-200 shadow-sm">
                {ebook.chapters[activeChapter].id === 'ch-conclusion' 
                    ? 'บทส่งท้าย' 
                    : `บทที่ ${activeChapter + 1}`} 
                <span className="text-stone-300 mx-2">|</span>
                {ebook.chapters.length} ส่วน
            </div>
        </div>

        <div className="flex flex-1 overflow-hidden">
            {/* TOC */}
            <div className="w-1/3 border-r border-stone-100 overflow-y-auto bg-stone-50/30 custom-scrollbar">
                <ul className="divide-y divide-stone-100">
                    {ebook.chapters.map((chapter, idx) => (
                        <li key={chapter.id} className="group relative hover:bg-amber-50/50 transition-colors">
                            <button
                                onClick={() => setActiveChapter(idx)}
                                className={`w-full text-left p-5 text-sm pr-12 transition-all ${activeChapter === idx ? 'bg-white text-amber-800 font-semibold border-l-4 border-amber-500 shadow-sm' : 'text-stone-600'}`}
                            >
                                <span className="block text-xs text-stone-400 mb-1 uppercase tracking-wider">
                                    {chapter.id === 'ch-conclusion' ? 'บทส่งท้าย' : `บทที่ ${idx + 1}`}
                                </span>
                                {chapter.title}
                            </button>
                            {/* Edit Button */}
                            <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  startEditing(idx, chapter.content || "");
                                }}
                                className="absolute right-3 top-1/2 -translate-y-1/2 p-1.5 text-stone-300 hover:text-amber-600 hover:bg-amber-100 rounded-lg transition-all opacity-0 group-hover:opacity-100"
                                title="แก้ไขเนื้อหา"
                            >
                                <PencilSquareIcon className="w-4 h-4" />
                            </button>
                        </li>
                    ))}
                </ul>
            </div>

            {/* Content */}
            <div className="w-2/3 overflow-y-auto p-10 bg-white custom-scrollbar">
                <h2 className="text-3xl font-bold text-stone-800 mb-8 border-b-2 border-amber-100 pb-6 font-promt leading-tight">
                    {ebook.chapters[activeChapter].title}
                </h2>
                <div className="prose prose-stone prose-lg max-w-none text-stone-700 leading-relaxed font-sarabun">
                    <ReactMarkdown components={{
                      img: ({node, ...props}) => <img style={{maxWidth: '100%', borderRadius: '12px', margin: '30px auto', display:'block', boxShadow: '0 4px 12px rgba(0,0,0,0.08)'}} {...props} />,
                      h2: ({node, ...props}) => <h2 className="text-amber-800 font-bold mt-8 mb-4" {...props} />,
                      h3: ({node, ...props}) => <h3 className="text-stone-800 font-semibold mt-6 mb-3" {...props} />,
                      blockquote: ({node, ...props}) => <blockquote className="border-l-4 border-amber-300 bg-amber-50 p-4 italic rounded-r-lg my-6 text-stone-600" {...props} />
                    }}>
                        {ebook.chapters[activeChapter].content || "ยังไม่มีเนื้อหา"}
                    </ReactMarkdown>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { Chapter, EBook } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("ไม่พบ API Key กรุณาตั้งค่า process.env.API_KEY");
  }
  return new GoogleGenAI({ apiKey });
};

// 1. Agent: Senior Strategist (15+ Years Experience)
export const generateBookOutline = async (topic: string): Promise<Partial<EBook>> => {
  const ai = getClient();

  const prompt = `
    You are a World-Class E-Book Strategist and Editor-in-Chief with over 15 years of experience in the publishing industry.
    You have a track record of creating best-selling non-fiction books globally.
    Your expertise lies in crafting compelling, market-driven book structures that hook readers instantly and deliver immense value.

    Your task is to plan a high-quality non-fiction e-book based on the user's topic: "${topic}".

    1. Create a magnetic, professional Title in Thai language that sounds like a bestseller (Catchy, Clear, and Compelling).
    2. Define a specific, high-potential Target Audience in Thai language.
    3. Write a captivating, high-converting Description in Thai language that emphasizes the benefits to the reader.
    4. Create an outline with exactly 5 distinct chapters. Each chapter must flow logically to build a complete narrative or guide.

    The content MUST be in Thai Language and reflect the depth, structure, and strategic thinking of a seasoned expert.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          targetAudience: { type: Type.STRING },
          description: { type: Type.STRING },
          chapters: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                summary: { type: Type.STRING } // Helper for the writer later
              },
              required: ["title", "summary"]
            }
          }
        },
        required: ["title", "targetAudience", "description", "chapters"]
      }
    }
  });

  if (!response.text) throw new Error("ไม่สามารถสร้างโครงเรื่องได้");

  const data = JSON.parse(response.text);

  // Transform to our internal Chapter type
  const chapters: Chapter[] = data.chapters.map((c: any, index: number) => ({
    id: `ch-${index}`,
    title: c.title,
    content: '',
    status: 'pending'
  }));

  // Add a Conclusion chapter explicitly
  chapters.push({
    id: 'ch-conclusion',
    title: 'บทสรุป: บทเรียนสำคัญและข้อคิดส่งท้าย',
    content: '',
    status: 'pending'
  });

  return {
    title: data.title,
    targetAudience: data.targetAudience,
    description: data.description,
    chapters: chapters
  };
};

// 2. Agent: Senior Ghostwriter (15+ Years Experience)
export const generateChapterContent = async (
  bookTitle: string, 
  chapterTitle: string, 
  audience: string,
  bookDescription: string,
  tone: string = "Professional & Authoritative",
  authorBio: string = ""
): Promise<string> => {
  const ai = getClient();

  const prompt = `
    You are a Senior Professional Ghostwriter and Editor with over 15 years of experience.

    Task: Write a chapter for a non-fiction e-book.

    Context:
    - Book Title: ${bookTitle}
    - Book Description: ${bookDescription}
    - Target Audience: ${audience}
    - Chapter Title: ${chapterTitle}

    Style & Voice Configuration:
    - Language: Thai (Eloquent, Natural, High-quality).
    - Tone of Voice: ${tone}.
    - Author Persona: ${authorBio ? `Write from the perspective of this author: "${authorBio}". Incorporate their expertise/vibe if applicable.` : 'Expert in the field.'}

    Requirements:
    - Length: Approximately 500-700 words.
    - Structure: Use engaging headers, concise paragraphs, and bullet points for readability. Format in Markdown.
    - Quality: Provide deep insights, practical real-world examples (use case studies if relevant to the topic), and avoid generic "AI-sounding" fluff.
    - Engagement: Speak directly to the reader ("คุณ").

    If this is the Conclusion chapter (บทสรุป), synthesize the wisdom into a powerful call-to-action.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: prompt,
  });

  return response.text || "เกิดข้อผิดพลาดในการสร้างเนื้อหา";
};

// 3. Agent: Senior Art Director (15+ Years Experience)
export const generateCoverImage = async (title: string, description: string, style: string = 'Minimalist'): Promise<string> => {
  const ai = getClient();

  // First, generate a prompt for the image model based on the book info
  const promptDesignResponse = await ai.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: `You are a Senior Art Director with 15 years of experience in Book Cover Design.
    Create a highly detailed, artistic image generation prompt for a non-fiction e-book cover.

    Book Title: "${title}". 
    Description: "${description}".
    Target Aesthetic Style: "${style}".

    Style Guidelines:
    - Focus heavily on the "${style}" visual style.
    - Ensure the design looks professional, eye-catching, and like a global Best Seller.
    - Use typography and visual hierarchy effectively.
    - Avoid text glitches (the image generation model should not render complex text, just the visual art).

    Output only the English prompt text for the image generator.`
  });

  const imagePrompt = promptDesignResponse.text || `A professional book cover for ${title} in ${style} style`;

  // Generate the actual image
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview', // Using the advanced image model
      contents: {
        parts: [{ text: imagePrompt }]
      },
      config: {
        imageConfig: {
            aspectRatio: "3:4", // Standard book ratio
            imageSize: "1K"
        }
      }
    });

    // Extract image
    for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
            return `data:image/png;base64,${part.inlineData.data}`;
        }
    }

    throw new Error("ไม่ได้รับข้อมูลรูปภาพกลับมาจาก API");

  } catch (e) {
    console.error("Image gen error", e);
    return "https://picsum.photos/600/800"; // Fallback
  }
};

