                    <div className="w-12 h-12 border-4 border-amber-200 border-t-amber-500 rounded-full animate-spin mb-4"></div>
                    <span className="text-amber-700 font-bold animate-pulse">AI กำลังปรับปรุงเนื้อหา...</span>
                </div>
            )}

            <div className="p-4 border-b border-stone-100 flex justify-between items-center bg-stone-50">
              <h3 className="font-bold text-stone-800 flex items-center gap-2">
                <PencilSquareIcon className="w-5 h-5 text-amber-600" /> 
                แก้ไขเนื้อหา: {editingIndex !== null && ebook.chapters[editingIndex]?.title}
              </h3>
              <button onClick={cancelEditing} className="text-stone-400 hover:text-stone-600 transition-colors bg-white p-1 rounded-full border border-stone-200 hover:bg-stone-100">
                <XMarkIcon className="w-6 h-6" />
              </button>
            </div>

            {/* Toolbar */}
            <div className="bg-stone-50 border-b border-stone-200 px-4 py-2 flex items-center gap-2 flex-wrap">
                {/* Media Tools */}
                <div className="flex items-center gap-2 mr-4">
                    <span className="text-[10px] font-bold text-stone-400 uppercase tracking-wider">Media</span>
                    <button 
                        onClick={() => fileInputRef.current?.click()}
                        className="p-1.5 bg-white border border-stone-200 rounded-lg text-stone-600 hover:bg-stone-100 transition-colors"
                        title="อัปโหลดรูป"
                    >
                        <PhotoIcon className="w-4 h-4" />
                    </button>
                    <button 
                        onClick={() => {
                            const url = prompt("กรุณาระบุ URL ของรูปภาพ:");
                            if (url) handleInsertImage(url);
                        }}
                        className="p-1.5 bg-white border border-stone-200 rounded-lg text-stone-600 hover:bg-stone-100 transition-colors"
                        title="แทรกรูปจาก URL"
                    >
                        <LinkIcon className="w-4 h-4" />
                    </button>
                    <input 
                        type="file" 
                        ref={fileInputRef} 
                        onChange={handleFileUpload} 
                        className="hidden" 
                        accept="image/*"
                    />
                </div>

                <div className="w-px h-6 bg-stone-300 mx-2"></div>

                {/* AI Tools */}
                <div className="flex items-center gap-2">
                    <span className="text-[10px] font-bold text-amber-500 uppercase tracking-wider flex items-center gap-1">
                        <SparklesIcon className="w-3 h-3" /> AI Assist
                    </span>
                    <button 
                        onClick={() => handleAiEdit('grammar')}
                        className="flex items-center gap-1 px-3 py-1.5 bg-white border border-amber-200 rounded-lg text-xs font-medium text-stone-700 hover:bg-amber-50 hover:text-amber-800 transition-colors"
                        title="ตรวจสอบคำผิดและไวยากรณ์"
                    >
                        <CheckBadgeIcon className="w-4 h-4 text-emerald-500" /> แก้คำผิด
                    </button>
                    <button 
                        onClick={() => handleAiEdit('rephrase')}
                        className="flex items-center gap-1 px-3 py-1.5 bg-white border border-amber-200 rounded-lg text-xs font-medium text-stone-700 hover:bg-amber-50 hover:text-amber-800 transition-colors"
                        title="ปรับประโยคให้ลื่นไหล อ่านง่ายขึ้น"
                    >
                        <ArrowsRightLeftIcon className="w-4 h-4 text-blue-500" /> เรียบเรียงใหม่
                    </button>
                    <button 
