                value={editingContent}
                onChange={(e) => setEditingContent(e.target.value)}
                className="w-full h-full p-8 resize-none focus:outline-none text-stone-800 leading-relaxed font-mono text-sm bg-transparent"
                placeholder="เขียนเนื้อหาที่นี่... รองรับ Markdown"
