                {ebook.chapters.length} ส่วน
            </div>
        </div>

        <div className="flex flex-1 overflow-hidden">
            {/* TOC */}
            <div className="w-1/3 border-r border-stone-100 overflow-y-auto bg-stone-50/30 custom-scrollbar">
