                            <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  startEditing(idx, chapter.content || "");
                                }}
                                className="absolute right-3 top-1/2 -translate-y-1/2 p-1.5 text-stone-300 hover:text-amber-600 hover:bg-amber-100 rounded-lg transition-all opacity-0 group-hover:opacity-100"
                                title="แก้ไขเนื้อหา"
                            >
                                <PencilSquareIcon className="w-4 h-4" />
                            </button>
