          <Icon className={`w-5 h-5 lg:w-6 lg:h-6 relative z-10 ${isActive ? 'animate-pulse' : ''}`} />
        </div>
        <span className={`mt-2 text-[10px] lg:text-xs font-semibold text-center hidden sm:block ${isActive ? 'text-amber-700' : isCompleted ? 'text-emerald-600' : 'text-stone-400'}`}>
           {label}
        </span>
      </div>
    );
  };

  // RENDER: API KEY INPUT SCREEN
  if (!apiKey) {
    return (
