               </a>
             </div>

             <button 
               onClick={() => setApiKey(tempApiKey)}
               disabled={!tempApiKey.trim()}
               className="w-full py-3.5 bg-stone-800 text-white rounded-xl font-bold hover:bg-stone-900 transition-all shadow-lg shadow-stone-300 disabled:opacity-50 disabled:cursor-not-allowed"
             >
               เริ่มต้นใช้งาน
             </button>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen pb-20 relative">
