                                        {tone === t.id && <div className="w-2.5 h-2.5 rounded-full bg-amber-600" />}
                                    </div>
                                    <div>
                                        <div className={`font-semibold text-sm ${tone === t.id ? 'text-amber-900' : 'text-stone-700'}`}>{t.label}</div>
                                        <div className="text-xs text-stone-400">{t.desc}</div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Style & Author */}
                    <div className="space-y-8">
                        {/* Cover Style */}
                        <div>
                            <label className="block text-stone-700 font-bold mb-4">
                                3. สไตล์ภาพปก (Design Style)
                            </label>
                            <div className="grid grid-cols-2 gap-2.5">
                                {COVER_STYLES.map((style) => (
                                    <button
                                    key={style.id}
                                    onClick={() => setCoverStyle(style.id)}
                                    className={`px-3 py-2.5 rounded-xl text-left transition-all border flex flex-col ${
                                        coverStyle === style.id
                                        ? 'bg-stone-800 text-white border-stone-800 shadow-lg shadow-stone-300'
                                        : 'bg-white border-stone-200 text-stone-600 hover:border-amber-400 hover:text-amber-700'
                                    }`}
                                    >
                                        <span className="font-bold text-sm">{style.label}</span>
                                        <span className={`text-[10px] ${coverStyle === style.id ? 'text-stone-300' : 'text-stone-400'}`}>
                                            {style.desc}
                                        </span>
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Author Bio */}
                        <div>
                             <label className="block text-stone-700 font-bold mb-3">
                                4. ข้อมูลผู้เขียน (Optional)
                            </label>
                            <textarea 
                                value={authorBio}
                                onChange={(e) => setAuthorBio(e.target.value)}
                                placeholder="เช่น ผู้เชี่ยวชาญด้านการตลาด 10 ปี, เจ้าของเพจ..., ชอบเล่าเรื่องตลก"
                                className="w-full px-4 py-3 text-sm border-2 border-stone-200 bg-stone-50 rounded-2xl focus:border-amber-500 focus:bg-white outline-none h-32 resize-none placeholder-stone-400"
                            ></textarea>
                            <p className="text-xs text-stone-400 mt-2 flex items-center gap-1">
                                <SparklesIcon className="w-3 h-3 text-amber-500" /> ช่วยให้ AI เขียนได้เหมือนคุณมากขึ้น
                            </p>
                        </div>
                    </div>
                </div>

                <div className="pt-8 border-t border-stone-100 flex justify-end">
                    <button
                        onClick={handleStartStrategy}
                        disabled={!topic.trim() || isProcessing}
                        className="bg-stone-800 text-white px-10 py-4 rounded-2xl font-bold text-lg hover:bg-stone-900 hover:scale-105 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 transition-all shadow-xl shadow-stone-300 flex items-center gap-3"
                    >
                        {isProcessing ? 'กำลังประมวลผล...' : 'เริ่มสร้าง E-Book'} <ArrowRightIcon className="w-5 h-5" />
                    </button>
                </div>

              </div>
            </div>
          </div>
        )}

        {/* STEP 2: APPROVAL SCREEN */}
        {step === WorkflowStep.APPROVAL && (
            <div className="max-w-5xl mx-auto mt-6 animate-fade-in">
                <div className="flex flex-col md:flex-row gap-6">
                    {/* Outline Preview */}
                    <div className="flex-1 bg-white/90 backdrop-blur-sm p-8 rounded-3xl shadow-xl border border-stone-200">
                        <div className="flex justify-between items-start mb-6">
                            <h2 className="text-2xl font-bold text-stone-800">ยืนยันโครงเรื่อง (Blueprint)</h2>
                            <span className="bg-amber-100 text-amber-800 text-xs px-3 py-1 rounded-full font-medium border border-amber-200">รอการอนุมัติ</span>
                        </div>

                        <div className="space-y-6">
                            <div className="p-6 bg-stone-50 rounded-2xl border border-stone-100">
                                <label className="text-xs font-bold text-stone-400 uppercase tracking-wider">ชื่อเรื่อง</label>
                                <h3 className="text-2xl font-bold text-stone-800 mt-2 font-promt leading-relaxed">{eBook.title}</h3>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div className="p-4 bg-white rounded-xl border border-stone-100 shadow-sm">
                                    <label className="text-xs font-bold text-stone-400 uppercase tracking-wider">กลุ่มเป้าหมาย</label>
                                    <p className="text-stone-700 text-sm mt-2">{eBook.targetAudience}</p>
                                </div>
                                <div className="p-4 bg-white rounded-xl border border-stone-100 shadow-sm">
                                    <label className="text-xs font-bold text-stone-400 uppercase tracking-wider">สไตล์การเขียน</label>
                                    <p className="text-stone-700 text-sm mt-2">{TONES.find(t => t.id === eBook.tone)?.label || eBook.tone}</p>
                                </div>
                            </div>

                            <div>
                                <div className="flex justify-between items-end mb-3">
                                    <label className="text-xs font-bold text-stone-400 uppercase tracking-wider">สารบัญ (แก้ไขได้)</label>
                                    <span className="text-[10px] text-stone-400">
                                        {eBook.chapters?.length || 0}/12 บท
                                    </span>
                                </div>
                                <div className="space-y-3">
                                    {eBook.chapters?.map((chap, idx) => (
                                        <div key={idx} className="flex items-center gap-3 p-3 bg-white border border-stone-100 rounded-xl shadow-sm hover:shadow-md transition-all group animate-fade-in">
                                            <div className="w-8 h-8 rounded-full bg-stone-100 text-stone-500 flex items-center justify-center font-bold text-xs shrink-0 border border-stone-200">
                                                {chap.id === 'ch-conclusion' ? 'End' : idx + 1}
                                            </div>

                                            <div className="flex-1 relative">
                                                <input 
                                                    type="text"
                                                    value={chap.title}
                                                    onChange={(e) => handleEditChapterTitle(idx, e.target.value)}
                                                    className="w-full text-stone-700 font-medium text-sm border-none bg-transparent focus:ring-0 p-0 hover:text-amber-800 transition-colors placeholder-stone-300"
                                                    placeholder="ใส่ชื่อบท..."
                                                />
                                                <PencilIcon className="w-3 h-3 text-stone-300 absolute right-0 top-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 pointer-events-none" />
                                            </div>

                                            {chap.id !== 'ch-conclusion' && (
                                                <button 
                                                    onClick={() => handleRemoveChapter(idx)}
                                                    className="p-1.5 text-stone-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors opacity-0 group-hover:opacity-100"
                                                    title="ลบบทนี้"
