                                        ? 'border-amber-500 bg-amber-50' 
                                        : 'border-stone-100 hover:border-amber-200 bg-white'
                                    }`}
                                >
                                    <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center transition-colors ${tone === t.id ? 'border-amber-600' : 'border-stone-300 group-hover:border-amber-300'}`}>
                                        {tone === t.id && <div className="w-2.5 h-2.5 rounded-full bg-amber-600" />}
                                    </div>
                                    <div>
                                        <div className={`font-semibold text-sm ${tone === t.id ? 'text-amber-900' : 'text-stone-700'}`}>{t.label}</div>
                                        <div className="text-xs text-stone-400">{t.desc}</div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Style & Author */}
                    <div className="space-y-8">
                        {/* Cover Style */}
                        <div>
                            <label className="block text-stone-700 font-bold mb-4">
                                3. สไตล์ภาพปก (Design Style)
                            </label>
                            <div className="grid grid-cols-2 gap-2.5">
                                {COVER_STYLES.map((style) => (
                                    <button
                                    key={style.id}
                                    onClick={() => setCoverStyle(style.id)}
                                    className={`px-3 py-2.5 rounded-xl text-left transition-all border flex flex-col ${
                                        coverStyle === style.id
                                        ? 'bg-stone-800 text-white border-stone-800 shadow-lg shadow-stone-300'
                                        : 'bg-white border-stone-200 text-stone-600 hover:border-amber-400 hover:text-amber-700'
                                    }`}
                                    >
                                        <span className="font-bold text-sm">{style.label}</span>
                                        <span className={`text-[10px] ${coverStyle === style.id ? 'text-stone-300' : 'text-stone-400'}`}>
