          ${isCompleted ? 'bg-emerald-500 border-emerald-500 text-white' : 
            isActive ? 'bg-amber-600 border-amber-600 text-white shadow-lg shadow-amber-200' : 
            'bg-white border-stone-200 text-stone-300'}`}>

          {/* Active Animations: Pulse Ring & Spin Border */}
          {isActive && (
            <>
                <span className="absolute inline-flex h-full w-full rounded-2xl bg-amber-400 opacity-20 animate-ping"></span>
