                            </p>
                        </div>
                    </div>
                </div>

                <div className="pt-8 border-t border-stone-100 flex justify-end">
                    <button
                        onClick={handleStartStrategy}
                        disabled={!topic.trim() || isProcessing}
                        className="bg-stone-800 text-white px-10 py-4 rounded-2xl font-bold text-lg hover:bg-stone-900 hover:scale-105 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 transition-all shadow-xl shadow-stone-300 flex items-center gap-3"
                    >
                        {isProcessing ? 'กำลังประมวลผล...' : 'เริ่มสร้าง E-Book'} <ArrowRightIcon className="w-5 h-5" />
                    </button>
                </div>

              </div>
            </div>
          </div>
        )}

        {/* STEP 2: APPROVAL SCREEN */}
        {step === WorkflowStep.APPROVAL && (
            <div className="max-w-5xl mx-auto mt-6 animate-fade-in">
                <div className="flex flex-col md:flex-row gap-6">
                    {/* Outline Preview */}
                    <div className="flex-1 bg-white/90 backdrop-blur-sm p-8 rounded-3xl shadow-xl border border-stone-200">
                        <div className="flex justify-between items-start mb-6">
                            <h2 className="text-2xl font-bold text-stone-800">ยืนยันโครงเรื่อง (Blueprint)</h2>
                            <span className="bg-amber-100 text-amber-800 text-xs px-3 py-1 rounded-full font-medium border border-amber-200">รอการอนุมัติ</span>
                        </div>

                        <div className="space-y-6">
                            <div className="p-6 bg-stone-50 rounded-2xl border border-stone-100">
                                <label className="text-xs font-bold text-stone-400 uppercase tracking-wider">ชื่อเรื่อง</label>
