        {/* STEP 0: INPUT CONFIGURATION */}
        {step === WorkflowStep.INPUT && (
          <div className="max-w-3xl mx-auto mt-6 animate-fade-in">
            <div className="bg-white/90 backdrop-blur-sm rounded-3xl shadow-xl shadow-stone-200/50 border border-stone-100 overflow-hidden">
