const FONT_OPTIONS = [
  { label: 'ค่าเริ่มต้น (Prompt)', value: '' },
  { label: 'Sarabun (เนื้อหา)', value: 'Sarabun' },
  { label: 'Serif (ทางการ)', value: 'ui-serif, Georgia, serif' },
