                            </div>
                        ))}
                      </div>
                   </div>
                </div>

                <div className="lg:col-span-1">
                   <AgentLog logs={logs} />
                </div>
              </div>
            )}

            {/* Final Result View */}
            {step === WorkflowStep.COMPLETED && (
               <BookPreview 
                  ebook={eBook as EBook} 
                  apiKey={apiKey}
                  onRestart={() => {
                    setTopic('');
                    setStep(WorkflowStep.INPUT);
                    setEBook({ chapters: [] });
                    setLogs([]);
                  }}
                  onUpdateChapter={handleUpdateChapter}
