                        <div className="mt-10 flex gap-4">
                            <button 
                                onClick={handleRegenerateOutline}
                                className="flex-1 py-3 px-4 bg-white border-2 border-stone-200 text-stone-600 rounded-xl font-semibold hover:border-stone-400 hover:text-stone-800 transition-all flex justify-center items-center gap-2"
                            >
