            <div className="absolute top-5 lg:top-6 left-10 right-10 h-0.5 bg-stone-200 -z-0"></div>
            <div className="absolute top-5 lg:top-6 left-10 h-0.5 bg-purple-500 transition-all duration-700 -z-0" 
