                              <span className="text-stone-400 shrink-0">
                                  {log.timestamp.toLocaleTimeString([], {minute:'2-digit', second:'2-digit'})}
                              </span>
                              <span>{log.message}</span>
                          </div>
                      ))}
                  </div>
               </div>
            </div>
