                  font-family: 'Sarabun', sans-serif; 
                  font-size: 16pt; 
                  line-height: 1.1; /* Line spacing 1.1 */
                  color: #000000;
                  background-color: #ffffff;
                  /* Simulating A5 on web view */
                  max-width: 148mm; 
                  min-height: 210mm;
                  margin: 0 auto;
                  padding: 1.5cm 2cm; 
                  box-sizing: border-box;
                  text-align: justify;
                  text-justify: inter-word;
              }

              img { max-width: 100%; height: auto; display: block; margin: 15px auto; border-radius: 4px; }

              /* Headings */
              h1 { font-family: 'Sarabun', sans-serif; font-weight: 700; font-size: 24pt; line-height: 1.2; margin-bottom: 0.5em; text-align: center; }
              h2 { font-family: 'Sarabun', sans-serif; font-weight: 700; font-size: 20pt; line-height: 1.2; margin-top: 1.5em; margin-bottom: 0.8em; border-bottom: 2px solid #eee; padding-bottom: 5px; }
              h3 { font-family: 'Sarabun', sans-serif; font-weight: 600; font-size: 18pt; margin-top: 1em; margin-bottom: 0.5em; }

              /* Paragraphs */
              p { margin-bottom: 10pt; text-indent: 0; }

              /* Lists */
              ul, ol { margin-bottom: 10pt; padding-left: 1cm; }
              li { margin-bottom: 5pt; }

              /* Blockquote */
              blockquote { border-left: 4px solid #ddd; padding-left: 15px; color: #555; font-style: italic; margin: 15px 0; background-color: #f9f9f9; padding: 10px; }

              /* Code */
              code { font-family: 'Courier New', monospace; background: #eee; padding: 2px 4px; border-radius: 3px; font-size: 0.9em; }
              pre { background: #f5f5f5; padding: 10px; border-radius: 5px; overflow-x: auto; margin-bottom: 15px; }

              /* Utilities */
              .page-break { page-break-after: always; display: block; }
              .text-center { text-align: center; }
              .text-right { text-align: right; }

              /* Print Specifics */
              @media print {
                  body { 
                      width: auto; 
                      margin: 0; 
                      padding: 0; 
                      box-shadow: none;
                  }
                  .page-break { page-break-after: always; }
              }
          </style>
      </head>
      <body>
          ${bodyContent}
      </body>
      </html>
    `;
  };

  const handleDownloadMarkdown = () => {
    let mdContent = `# ${ebook.title}\n\n`;
    mdContent += `> ${ebook.description}\n\n`;
    mdContent += `**กลุ่มเป้าหมาย:** ${ebook.targetAudience}\n\n`;
    mdContent += `---\n\n`;

    ebook.chapters.forEach(chap => {
        mdContent += `# ${chap.title}\n\n`;
        mdContent += `${chap.content}\n\n`;
        mdContent += `---\n\n`;
    });

    downloadFile(mdContent, `${ebook.title}.md`, 'text/markdown');
  };

  const handleDownloadHTML = async () => {
    const html = await getFullHTML();
    downloadFile(html, `${ebook.title}.html`, 'text/html');
  };

  const handleDownloadEPUB = async () => {
    setIsExportingEPUB(true);
    try {
        const zip = new JSZip();

        // 1. mimetype
        zip.file("mimetype", "application/epub+zip");

        // 2. META-INF/container.xml
        zip.folder("META-INF")?.file("container.xml", `<?xml version="1.0"?>
<container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container">
   <rootfiles>
      <rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml"/>
   </rootfiles>
</container>`);

        // 3. OEBPS folder
        const oebps = zip.folder("OEBPS");
        if(!oebps) return;

        // CSS - Updated for A5 style logic (16pt Sarabun)
        oebps.file("style.css", `
            @import url('https://fonts.googleapis.com/css2?family=Sarabun:wght@300;400;500;700&display=swap');
            body { 
                font-family: 'Sarabun', sans-serif; 
                line-height: 1.1; 
                color: #000; 
                font-size: 16pt;
